IF NOT EXISTS(SELECT * FROM sys.columns WHERE Name = N'LogoImageID_Ext' AND Object_ID = Object_ID(N'SysTab'))
BEGIN
aLTER TABLE SysTab ADD LogoImageID_Ext int NULL
DECLARE @v sql_variant 
SET @v = N'Logo Image ID'
EXECUTE sp_addextendedproperty N'MS_Description', @v, N'SCHEMA', N'dbo', N'TABLE', N'SysTab', N'COLUMN', N'LogoImageID_Ext'
end
go

