--Alokasi Blanket No untuk Scheme Verify belum menggunakan Blanket Type Version (Fungsi Scheme_Verify)

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QTOC_GENHTAB') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN DROP PROCEDURE QTOC_GENHTAB  END 
GO

CREATE PROCEDURE QTOC_GENHTAB (@P_TOC AS VARCHAR(10))     
AS     
SELECT  TOP 1     
TOC.TOC, TOC.DESCRIPTION, TOC.ANNUALTREATYF, TOC.NORISKACCUMULATIONF, TOC.BlanketTypeVer,
TOC.IACCREG, TOC.REGID, TOC.LBL_PHOLDER, TOC.LBL_AID, TOC.EXCLUSIVEF,     
TOC.FLDID1, TOC.FLDTAG1, TOC.FLDTAGA1, GENHTAB_1.FLDTAB AS FLDTAB1, GENHTAB_1.FLDCOM AS FLDCOM1, GENHTAB_1.FLDCOMA AS FLDCOMA1, GENHTAB_1.FLDDFORMAT AS FLDDFORMAT1, GENHTAB_1.FLDIFORMAT AS FLDIFORMAT1, GENHTAB_1.FLDTYPE AS FLDTYPE1, GENHTAB_1.SUBLINKF AS SUBLINKF1,  GENHTAB_1.FLDSEARCH AS FLDSEARCH1, GENHTAB_1.FLDCRITERIA AS FLDCRITERIA1, GENHTAB_1.FLDCHGINF as FLDCHGINF1,     
TOC.FLDID2, TOC.FLDTAG2, TOC.FLDTAGA2, GENHTAB_2.FLDTAB AS FLDTAB2, GENHTAB_2.FLDCOM AS FLDCOM2, GENHTAB_2.FLDCOMA AS FLDCOMA2, GENHTAB_2.FLDDFORMAT AS FLDDFORMAT2, GENHTAB_2.FLDIFORMAT AS FLDIFORMAT2, GENHTAB_2.FLDTYPE AS FLDTYPE2, GENHTAB_2.SUBLINKF AS SUBLINKF2,  GENHTAB_2.FLDSEARCH AS FLDSEARCH2, GENHTAB_2.FLDCRITERIA AS FLDCRITERIA2, GENHTAB_2.FLDCHGINF as FLDCHGINF2,     
TOC.FLDID3, TOC.FLDTAG3, TOC.FLDTAGA3, GENHTAB_3.FLDTAB AS FLDTAB3, GENHTAB_3.FLDCOM AS FLDCOM3, GENHTAB_3.FLDCOMA AS FLDCOMA3, GENHTAB_3.FLDDFORMAT AS FLDDFORMAT3, GENHTAB_3.FLDIFORMAT AS FLDIFORMAT3, GENHTAB_3.FLDTYPE AS FLDTYPE3, GENHTAB_3.SUBLINKF AS SUBLINKF3,  GENHTAB_3.FLDSEARCH AS FLDSEARCH3, GENHTAB_3.FLDCRITERIA AS FLDCRITERIA3, GENHTAB_3.FLDCHGINF as FLDCHGINF3,     
TOC.FLDID4, TOC.FLDTAG4, TOC.FLDTAGA4, GENHTAB_4.FLDTAB AS FLDTAB4, GENHTAB_4.FLDCOM AS FLDCOM4, GENHTAB_4.FLDCOMA AS FLDCOMA4, GENHTAB_4.FLDDFORMAT AS FLDDFORMAT4, GENHTAB_4.FLDIFORMAT AS FLDIFORMAT4, GENHTAB_4.FLDTYPE AS FLDTYPE4, GENHTAB_4.SUBLINKF AS SUBLINKF4,  GENHTAB_4.FLDSEARCH AS FLDSEARCH4, GENHTAB_4.FLDCRITERIA AS FLDCRITERIA4, GENHTAB_4.FLDCHGINF as FLDCHGINF4,     
TOC.FLDID5, TOC.FLDTAG5, TOC.FLDTAGA5, GENHTAB_5.FLDTAB AS FLDTAB5, GENHTAB_5.FLDCOM AS FLDCOM5, GENHTAB_5.FLDCOMA AS FLDCOMA5, GENHTAB_5.FLDDFORMAT AS FLDDFORMAT5, GENHTAB_5.FLDIFORMAT AS FLDIFORMAT5, GENHTAB_5.FLDTYPE AS FLDTYPE5, GENHTAB_5.SUBLINKF AS SUBLINKF5,  GENHTAB_5.FLDSEARCH AS FLDSEARCH5, GENHTAB_5.FLDCRITERIA AS FLDCRITERIA5, GENHTAB_5.FLDCHGINF as FLDCHGINF5,     
TOC.FLDID6, TOC.FLDTAG6, TOC.FLDTAGA6, GENHTAB_6.FLDTAB AS FLDTAB6, GENHTAB_6.FLDCOM AS FLDCOM6, GENHTAB_6.FLDCOMA AS FLDCOMA6, GENHTAB_6.FLDDFORMAT AS FLDDFORMAT6, GENHTAB_6.FLDIFORMAT AS FLDIFORMAT6, GENHTAB_6.FLDTYPE AS FLDTYPE6, GENHTAB_6.SUBLINKF AS SUBLINKF6,  GENHTAB_6.FLDSEARCH AS FLDSEARCH6, GENHTAB_6.FLDCRITERIA AS FLDCRITERIA6, GENHTAB_6.FLDCHGINF as FLDCHGINF6,     
TOC.FLDID7, TOC.FLDTAG7, TOC.FLDTAGA7, GENHTAB_7.FLDTAB AS FLDTAB7, GENHTAB_7.FLDCOM AS FLDCOM7, GENHTAB_7.FLDCOMA AS FLDCOMA7, GENHTAB_7.FLDDFORMAT AS FLDDFORMAT7, GENHTAB_7.FLDIFORMAT AS FLDIFORMAT7, GENHTAB_7.FLDTYPE AS FLDTYPE7, GENHTAB_7.SUBLINKF AS SUBLINKF7,  GENHTAB_7.FLDSEARCH AS FLDSEARCH7, GENHTAB_7.FLDCRITERIA AS FLDCRITERIA7, GENHTAB_7.FLDCHGINF as FLDCHGINF7,     
TOC.FLDID8, TOC.FLDTAG8, TOC.FLDTAGA8, GENHTAB_8.FLDTAB AS FLDTAB8, GENHTAB_8.FLDCOM AS FLDCOM8, GENHTAB_8.FLDCOMA AS FLDCOMA8, GENHTAB_8.FLDDFORMAT AS FLDDFORMAT8, GENHTAB_8.FLDIFORMAT AS FLDIFORMAT8, GENHTAB_8.FLDTYPE AS FLDTYPE8, GENHTAB_8.SUBLINKF AS SUBLINKF8,  GENHTAB_8.FLDSEARCH AS FLDSEARCH8, GENHTAB_8.FLDCRITERIA AS FLDCRITERIA8, GENHTAB_8.FLDCHGINF as FLDCHGINF8,     
TOC.FLDID9, TOC.FLDTAG9, TOC.FLDTAGA9, GENHTAB_9.FLDTAB AS FLDTAB9, GENHTAB_9.FLDCOM AS FLDCOM9, GENHTAB_9.FLDCOMA AS FLDCOMA9, GENHTAB_9.FLDDFORMAT AS FLDDFORMAT9, GENHTAB_9.FLDIFORMAT AS FLDIFORMAT9, GENHTAB_9.FLDTYPE AS FLDTYPE9, GENHTAB_9.SUBLINKF AS SUBLINKF9,  GENHTAB_9.FLDSEARCH AS FLDSEARCH9, GENHTAB_9.FLDCRITERIA AS FLDCRITERIA9, GENHTAB_9.FLDCHGINF as FLDCHGINF9,     
TOC.FLDID10, TOC.FLDTAG10, TOC.FLDTAGA10, GENHTAB_10.FLDTAB AS FLDTAB10, GENHTAB_10.FLDCOM AS FLDCOM10, GENHTAB_10.FLDCOMA AS FLDCOMA10, GENHTAB_10.FLDDFORMAT AS FLDDFORMAT10, GENHTAB_10.FLDIFORMAT AS FLDIFORMAT10, GENHTAB_10.FLDTYPE AS FLDTYPE10, GENHTAB_10.SUBLINKF AS SUBLINKF10,  GENHTAB_10.FLDSEARCH AS FLDSEARCH10, GENHTAB_10.FLDCRITERIA AS FLDCRITERIA10, GENHTAB_10.FLDCHGINF as FLDCHGINF10,     
TOC.FLDID11, TOC.FLDTAG11, TOC.FLDTAGA11, GENHTAB_11.FLDTAB AS FLDTAB11, GENHTAB_11.FLDCOM AS FLDCOM11, GENHTAB_11.FLDCOMA AS FLDCOMA11, GENHTAB_11.FLDDFORMAT AS FLDDFORMAT11, GENHTAB_11.FLDIFORMAT AS FLDIFORMAT11, GENHTAB_11.FLDTYPE AS FLDTYPE11, GENHTAB_11.SUBLINKF AS SUBLINKF11,  GENHTAB_11.FLDSEARCH AS FLDSEARCH11, GENHTAB_11.FLDCRITERIA AS FLDCRITERIA11, GENHTAB_11.FLDCHGINF as FLDCHGINF11,     
TOC.FLDID12, TOC.FLDTAG12, TOC.FLDTAGA12, GENHTAB_12.FLDTAB AS FLDTAB12, GENHTAB_12.FLDCOM AS FLDCOM12, GENHTAB_12.FLDCOMA AS FLDCOMA12, GENHTAB_12.FLDDFORMAT AS FLDDFORMAT12, GENHTAB_12.FLDIFORMAT AS FLDIFORMAT12, GENHTAB_12.FLDTYPE AS FLDTYPE12, GENHTAB_12.SUBLINKF AS SUBLINKF12,  GENHTAB_12.FLDSEARCH AS FLDSEARCH12, GENHTAB_12.FLDCRITERIA AS FLDCRITERIA12, GENHTAB_12.FLDCHGINF as FLDCHGINF12,     
TOC.FLDID13, TOC.FLDTAG13, TOC.FLDTAGA13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDCOMA AS FLDCOMA13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  GENHTAB_13.FLDSEARCH AS FLDSEARCH13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13, GENHTAB_13.FLDCHGINF as FLDCHGINF13,     
TOC.FLDID14, TOC.FLDTAG14, TOC.FLDTAGA14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDCOMA AS FLDCOMA14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  GENHTAB_14.FLDSEARCH AS FLDSEARCH14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14, GENHTAB_14.FLDCHGINF as FLDCHGINF14,     
TOC.FLDID15, TOC.FLDTAG15, TOC.FLDTAGA15, GENHTAB_15.FLDTAB AS FLDTAB15, GENHTAB_15.FLDCOM AS FLDCOM15, GENHTAB_15.FLDCOMA AS FLDCOMA15, GENHTAB_15.FLDDFORMAT AS FLDDFORMAT15, GENHTAB_15.FLDIFORMAT AS FLDIFORMAT15, GENHTAB_15.FLDTYPE AS FLDTYPE15, GENHTAB_15.SUBLINKF AS SUBLINKF15,  GENHTAB_15.FLDSEARCH AS FLDSEARCH15, GENHTAB_15.FLDCRITERIA AS FLDCRITERIA15, GENHTAB_15.FLDCHGINF as FLDCHGINF15     
FROM     
TOC     
LEFT OUTER JOIN GENHTAB as GENHTAB_1 ON TOC.FLDID1 = GENHTAB_1.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_2 ON TOC.FLDID2 = GENHTAB_2.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_3 ON TOC.FLDID3 = GENHTAB_3.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_4 ON TOC.FLDID4 = GENHTAB_4.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_5 ON TOC.FLDID5 = GENHTAB_5.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_6 ON TOC.FLDID6 = GENHTAB_6.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_7 ON TOC.FLDID7 = GENHTAB_7.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_8 ON TOC.FLDID8 = GENHTAB_8.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_9 ON TOC.FLDID9 = GENHTAB_9.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_10 ON TOC.FLDID10 = GENHTAB_10.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_11 ON TOC.FLDID11 = GENHTAB_11.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_12 ON TOC.FLDID12 = GENHTAB_12.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_13 ON TOC.FLDID13 = GENHTAB_13.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_14 ON TOC.FLDID14 = GENHTAB_14.FLDID     
LEFT OUTER JOIN GENHTAB as GENHTAB_15 ON TOC.FLDID15 = GENHTAB_15.FLDID     
WHERE  TOC.TOC = @P_TOC     
GO

--Perubahan Display Premium Calculation jika Premi di atas 2 Decimal

if exists (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'DISPLAY_CALCULATION') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) )
BEGIN DROP FUNCTION DISPLAY_CALCULATION END
GO

CREATE FUNCTION DISPLAY_CALCULATION(@P_ANO int)              
RETURNS TABLE  AS              
RETURN (              
Select A.ANO, D1.Code, D1.SDate, D1.EDate, D1.Gross, D2.Prorata, D1.Currency,  D1.Calculation as Premium_Calculation, D2.Prorata_Calculation,              
D1.Calculation   
+ Case When D2.Prorata=0 or D2.Prorata_Calculation='' Then '' else ' x '+D2.Prorata_Calculation end              
+ Case When A.Qty>1 Then ' x '+ Convert(varchar(25), Cast(A.Qty as Int),1) Else '' end              
+ ' = '   
+ replace(convert(varchar(50), cast(round(D1.Gross*(Case When D2.Prorata<>0 or D2.Prorata_Calculation<>'' Then D2.Prorata else 1 end)*Case When A.Qty>1 Then A.Qty Else 1 End,0) as Money),1),'0.00',convert(varchar(50), cast(D1.Gross*(Case When D2.Prorata<>0 or D2.Prorata_Calculation<>'' Then D2.Prorata else 1 end)*Case When A.Qty>1 Then A.Qty Else 1 End-round(D1.Gross*(Case When D2.Prorata<>0 or D2.Prorata_Calculation<>'' Then D2.Prorata else 1 end)*Case When A.Qty>1 Then A.Qty Else 1 End,0) as Money),2)) 
as Calculation,              
dbo.Premium_Discount(D1.ANO, D1.Code,cast(datediff(Month,A.SDate, D1.SDate) as integer) / 12 + 1) as Discount, dbo.Premium_Commission(D1.ANO, D1.Code,cast(datediff(Month,A.SDate, D1.SDate) as integer) / 12 + 1,0) as Commission              
from Display_Gross_Calculation(@P_ANO) D1, Display_Prorata_Calculation(@P_ANO) D2, Acceptance A              
Where a.ANO = D1.ANO And D1.ANO = D2.ANO And D1.Currency = D2.Currency And D1.Code = D2.Code And D1.SDate = D2.SDate And D1.EDate = D2.EDate and D2.Prorata<>0               
)                
go

if exists (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'Payor_Discount') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) )
BEGIN DROP FUNCTION Payor_Discount END
GO
--Koreksi Script Simulasi Perhitungan Payor Discount
CREATE Function Payor_Discount(@P_ANO as int,@P_Code as varchar(10),@P_Period as int=0)          
RETURNS @DISCOUNT TABLE (GDISCOUNT Float, PDISCOUNT Float, DISCOUNT Float)  
AS          
BEGIN          
 Declare @PDiscount Float          
 Declare @GDiscount Float          
 Declare @TDiscount Float          
 Declare @RegNo varchar(20)    
 Declare @AStatus varchar(1)    
 Declare @LANO int
 Declare @OANO int
                
 Select @RegNo=RegNo, @AStatus=AStatus, @LANO=LANO, @OANO=OANO from Acceptance Where ANO=@P_ANO    

 if @LANO=-1
 BEGIN
	  Select @PDiscount=Payor.Discount, @GDiscount=Payor.GDiscount, @TDiscount=PayorDet.Discount
	  from Acceptance 
	  Left Join Payor on (Payor.ANO=Acceptance.ANO)
	  Left Join PayorDet on (PayorDet.ANO=Payor.ANO and PayorDet.Code=@P_Code and (PayorDet.Period=0 or PayorDet.Period=@P_Period))      	  
	  Where Acceptance.ANO=@P_ANO  
	  if @TDiscount is not null          
		 Select @PDiscount=@TDiscount 	  
 END
 ELSE
 BEGIN 
 
	  -- Payor Discount from Alternate Discount          
	 Select @PDiscount=APayor.Discount from APayor Where ANO=@P_ANO          
	 if @PDiscount is null          
	 BEGIN           
		if @RegNo='' or @AStatus in ('W','T') or @P_ANO=@OANO   
		Begin       
		  Select @PDiscount=Payor.Discount, @GDiscount=Payor.GDiscount, @TDiscount=PayorDet.Discount
		  from Acceptance 
		  Inner Join Acceptance mAcceptance on (mAcceptance.ANO=mAcceptance.LANO and mAcceptance.ANO=Acceptance.LANO)
		  Left Join Payor on (Payor.ANO=mAcceptance.ANO)
		  Left Join PayorDet on (PayorDet.ANO=Payor.ANO and PayorDet.Code=@P_Code and (PayorDet.Period=0 or PayorDet.Period=@P_Period))  	  
		  Where Acceptance.ANO=@P_ANO and Acceptance.AStatus in ('W','T')
	    end    
	    else    
	    Begin    
		  Select @PDiscount=Payor.Discount, @GDiscount=Payor.GDiscount, @TDiscount=PayorDet.Discount
		  from Acceptance 
		  Inner Join Acceptance mAcceptance on (mAcceptance.ANO=mAcceptance.LANO and ((mAcceptance.RegNo<>'' and mAcceptance.RegNo=Acceptance.RegNo)))
		  Left Join Payor on (Payor.ANO=mAcceptance.ANO)
		  Left Join PayorDet on (PayorDet.ANO=Payor.ANO and PayorDet.Code=@P_Code and (PayorDet.Period=0 or PayorDet.Period=@P_Period))  	  
		  Where Acceptance.ANO=@P_ANO and Acceptance.RegNo<>'' and Acceptance.AStatus not in ('W','T') 
	    end    
		if @TDiscount is not null          
			Select @PDiscount=@TDiscount                  
	 End          
	 Else          
	 BEGIN          
		Select @TDiscount=PayorDet.Discount from APayorDet PayorDet Where PayorDet.ANO=@P_ANO and PayorDet.Code=@P_Code and (PayorDet.Period=0 or PayorDet.Period=@P_Period)          
		if @TDiscount is not null          
			Select @PDiscount=@TDiscount          
		Select @GDiscount=0          
	 End          
 END
                        
 insert into @Discount(GDiscount, PDiscount, Discount) Select @GDiscount, @PDiscount, @GDiscount+(1 - @GDiscount / 100)*@PDiscount          
 Return  
End          

GO

--Koreksi untuk Perhitungan Adjusment Overlimit jika terdapat Cancel All
IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'BALANCE_ACCASS_ADJUSTMENT') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN DROP PROCEDURE BALANCE_ACCASS_ADJUSTMENT  END 
GO
CREATE Procedure BALANCE_ACCASS_ADJUSTMENT(@P_ANO integer)     
as     
Select AccAss.*, A2.PDate, A2.PPDate     
From Acceptance A1     
inner join Acceptance A2 on (A2.OANO=A1.OANO)     
inner join AccAss on (AccAss.ANO=A2.ANO)     
Left join Acceptance pA1  on (pA1.ANO=A2.pANO)     
Where A1.ANO=@P_ANO and A2.ANO<A1.ANO     
and   
(     
 (  
 A2.ANO<=A1.PANO and A1.PDate<=A2.PDate and A1.PPDate>=A2.PPDate and A1.AType='A' and (A2.AType<>'A' and coalesce(pA1.AType,'')<>'A')   
 and AccAss.AdjustableF=1 and AccAss.AdjMethod<>'OVERLIMIT'  
 and NOT EXISTS (Select PANO from Acceptance A3 Where A3.PANO=A2.ANO and A3.Astatus<>'C' and A3.AType='A' and A3.ANO<>@P_ANO)  
 )     
 or   
 (  
 A2.ANO<=A1.PANO and A1.PDate<=A2.PDate and A1.PPDate>=A2.PPDate and A1.AType='A' and (A2.AType<>'A' and coalesce(pA1.AType,'')<>'A')   
 and AccAss.AdjustableF=1 and AccAss.AdjMethod='OVERLIMIT' and A2.PDATE<A2.PPDATE and AccAss.CAmount<>0  
 and NOT EXISTS (Select PANO from Acceptance A3 Where A3.PANO=A2.ANO and A3.Astatus<>'C' and A3.AType='A' and A3.ANO<>@P_ANO)  
 )     
 or    
 (  
 A1.AType='C' and A1.EMethod='A' and A2.PDate>=A1.PDate and (coalesce(pA1.pDate,A2.PDate)>=A1.PDate or A2.ATYPE='A' or (coalesce(pA1.pDate,A2.PDate)<A1.PDate and AccAss.CAmount<>0))  
 )     
)     
     
go


--Perubahan Script untuk Query Policy Data
IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'qPolicyData') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN DROP PROCEDURE qPolicyData  END 
GO
Create procedure qPolicyData(@P_SQLFilter as varchar(2048))          
as  
  
Declare @SQL as varchar(8000)  
  
Select @P_SQLFILTER=replace(@P_SQLFILTER,'``','''')
  
Select @SQL=''      
Select @SQL = @SQL + ' Select *'  
Select @SQL = @SQL + ' from '  
Select @SQL = @SQL + ' ('  
Select @SQL = @SQL + '  SELECT ACCEPTANCE.ANO, COVER.TOC AS TOC, COVER.INSURED AS Insured, ACCEPTANCE.AName AS AName, COVER.COVERNO, ACCEPTANCE.REGNO, ACCEPTANCE.POLICYNO AS PolicyNo, ACCEPTANCE.CERTIFICATENO AS CertificateNo, ACCEPTANCE.REFNO, Acceptance.PDate, Acceptance.PPDate,       '  
Select @SQL = @SQL + '  AINFO.VALUEID1, AINFO.VALUEDESC1,      '  
Select @SQL = @SQL + '  AINFO.VALUEID2, AINFO.VALUEDESC2,      '  
Select @SQL = @SQL + '  AINFO.VALUEID3, AINFO.VALUEDESC3,      '  
Select @SQL = @SQL + '  AINFO.VALUEID4, AINFO.VALUEDESC4,      '  
Select @SQL = @SQL + '  AINFO.VALUEID5, AINFO.VALUEDESC5,      '  
Select @SQL = @SQL + '  AINFO.VALUEID6, AINFO.VALUEDESC6,      '  
Select @SQL = @SQL + '  AINFO.VALUEID7, AINFO.VALUEDESC7,      '  
Select @SQL = @SQL + '  AINFO.VALUEID8, AINFO.VALUEDESC8,      '  
Select @SQL = @SQL + '  AINFO.VALUEID9, AINFO.VALUEDESC9,      '  
Select @SQL = @SQL + '  AINFO.VALUEID10, AINFO.VALUEDESC10,     '   
Select @SQL = @SQL + '  AINFO.VALUEID11, AINFO.VALUEDESC11,      '  
Select @SQL = @SQL + '  AINFO.VALUEID12, AINFO.VALUEDESC12,      '  
Select @SQL = @SQL + '  AINFO.VALUEID13, AINFO.VALUEDESC13,      '  
Select @SQL = @SQL + '  AINFO.VALUEID14, AINFO.VALUEDESC14,      '  
Select @SQL = @SQL + '  AINFO.VALUEID15, AINFO.VALUEDESC15      '  
Select @SQL = @SQL + '  FROM DBO.COVER as COVER INNER JOIN  DBO.ACCEPTANCE ACCEPTANCE ON COVER.CNO = ACCEPTANCE.CNO INNER JOIN  DBO.AINFO AINFO ON ACCEPTANCE.ANO = AINFO.ANO            '  
Select @SQL = @SQL + '  WHERE (ACCEPTANCE.ANO <> ACCEPTANCE.LANO) AND (ACCEPTANCE.ATYPE NOT IN (''C'', ''A'')) AND (ACCEPTANCE.ASTATUS NOT IN (''W'',''T'')) AND NOT (COVER.CSTATUS=''C'' AND ACCEPTANCE.ASTATUS=''C'') AND datediff(day, ACCEPTANCE.PDATE,ACCEPTANCE.PPDATE)>0 AND ACCEPTANCE.POLICYNO<>''''                '  
Select @SQL = @SQL + ' ) Q'  
if @P_SQLFilter<>''  
 Select @SQL = @SQL + ' Where ' + @P_SQLFilter  

Execute (@SQL)  

GO


--Penambahan Stored Procedure untuk Penghapusan Detail Acceptance, Cover, dan Claim

Begin Tran

Declare @Table_Name as varchar(100)
Declare @Const_Name as varchar(100)

Declare Object_Cursor Cursor for 
Select S1.Name, S2.Name 
from sys.Foreign_keys S1, sys.Objects S2 Where S2.Object_ID=S1.Parent_Object_ID and S1.Type='F'
and OBJECT_NAME (S1.referenced_object_id) in  ('Acceptance','Cover','Claim')


Open Object_Cursor
FETCH FROM Object_Cursor into @Const_Name, @Table_Name
WHILE @@FETCH_STATUS = 0  
BEGIN  	
	execute ('Alter Table '+@Table_Name+' Drop Constraint '+@Const_Name)
		
	FETCH Next FROM Object_Cursor into @Const_Name, @Table_Name
End  
Close Object_Cursor  
Deallocate Object_Cursor
 
Commit

GO

