		  Where Acceptance.ANO=@P_ANO and (AccBS.GrossUpF=1 or AccBS.NetUpF=1)  		

		  if @GrossUpComm is null    
			 Select @GrossUpComm=0              
		  
		  Select @VAT=        
		   sum(  
		   (  
			Case When AccBS.GrossF=1 then  
				coalesce(AccBSDet.Fee,AccBS.Fee)*100/(100-@RDiscount)  
