		  and (AccBS.NotMinimumPremiumF=0 or (AccBS.NotMinimumPremiumF=1 and @P_MinimumPremiumF=0))                      
	 end
 
 END
                        
 if @TAX is null                
   Select @TAX=0                
                        
 return(@TAX)                
End        
    
GO

