CREATE function VOUCHER_LAPSE(@P_Date as smalldatetime, @P_Lapse1 as   smallint, @P_Lapse2 as smallint)  
RETURNS TABLE  
AS RETURN  
(  
select OV.* from OVoucher() as OV Where datediff(day,OV.DueDate,convert(smalldatetime,@P_Date))>=@P_Lapse1 and datediff(day,OV.DueDate,convert(smalldatetime,@P_Date))<=@P_Lapse2  
)  
GO


