IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'AutoExpiry_Process') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN DROP PROCEDURE AutoExpiry_Process END
GO
CREATE Procedure AutoExpiry_Process(@P_PDate as smalldatetime)                                
as                       
Select Acceptance.PolicyNo, Acceptance.CertificateNo, Acceptance.ANO, Acceptance.LANO, Cover.OpenFlag, Cover.CNO, Acceptance.EDate from Acceptance, Cover, TOC           
Where (Cover.CNO = Acceptance.CNO And (Acceptance.LANO = -1 Or (Cover.OpenFlag = 1 And Acceptance.LANO <> Acceptance.ANO) Or (Cover.OpenFlag = 0 And Acceptance.LANO=Acceptance.ANO)))          
and TOC.TOC=Cover.TOC    
and Acceptance.AStatus='I' and Acceptance.AType not in ('C','A') and datediff(day, dateadd(day, Acceptance.ExtPeriod,Acceptance.EDate),@P_PDate)>=TOC.EltDays and TOC.EltDays<>0          
and Cover.ISType not in ('T') --Exclude Inward Treaty  
and Acceptance.ANO not in (Select PANO from Acceptance EA Where EA.PANO=Acceptance.ANO)          
go

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'AutoInforce_Process') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN DROP PROCEDURE AutoInforce_Process END
GO
CREATE Procedure AutoInforce_Process(@P_PDate as smalldatetime)                                                
as                                       
--Individual Polis First    
Select AIBucket.ADate, AIBucket.PID, Acceptance.ANO, Acceptance.LANO, Acceptance.RegNo, Acceptance.BatchNo, cast(0 as Bit) as BulkF                  
from AIBucket, Acceptance, Cover                    
where AIBucket.Status='R'     
and Acceptance.RegNo=AIBucket.RegNo and Acceptance.LANO=-1    
and Cover.CNO=Acceptance.CNO and Cover.CStatus='A' and Acceptance.AStatus='W'         
and Acceptance.CDate<=AIBucket.Last_Update     
    
Union All    
    
--Certificate Second    
Select AIBucket.ADate, AIBucket.PID, Acceptance.ANO, Acceptance.LANO, Acceptance.RegNo, Acceptance.BatchNo, cast(0 as Bit) as BulkF    
from AIBucket, Acceptance, Cover                    
where AIBucket.Status='R'     
and Acceptance.RegNo=AIBucket.RegNo and Acceptance.CertificateNo<>'' and Acceptance.CertificateNo=AIBucket.CertificateNo and Acceptance.ANO<>Acceptance.LANO and Cover.OpenFlag=1                  
and Cover.CNO=Acceptance.CNO and Cover.CStatus='A' and Acceptance.AStatus='W'         
and Acceptance.CDate<=AIBucket.Last_Update     
    
Union All    
    
--Bulk Inforce Certificate    
Select AIBucket.ADate, AIBucket.PID, Max(Acceptance.LANO) as ANO, Max(Acceptance.LANO) as LANO, Max(Acceptance.RegNo) as RegNo, Acceptance.BatchNo, cast(1 as Bit) as BulkF                  
from AIBucket, Acceptance, Cover                    
where AIBucket.Status='R'     
and Acceptance.RegNo=AIBucket.RegNo and Acceptance.CertificateNo='' and Acceptance.BatchNo=AIBucket.BatchNo and Acceptance.ANO<>Acceptance.LANO and Cover.OpenFlag=1                  
and Cover.CNO=Acceptance.CNO and Cover.CStatus='A' and Acceptance.AStatus='W'         
and Acceptance.CDate<=AIBucket.Last_Update     
Group By AIBucket.ADate, AIBucket.PID, Acceptance.BatchNo    
    
Union All    
    
--Fleet Polis Last    
Select AIBucket.ADate, AIBucket.PID, Acceptance.ANO, Acceptance.LANO, Acceptance.RegNo, Acceptance.BatchNo, cast(0 as Bit) as BulkF    
from AIBucket, Acceptance, Cover                    
where AIBucket.Status='R'     
and Acceptance.RegNo=AIBucket.RegNo and Acceptance.BatchNo='' and Acceptance.CertificateNo='' and Acceptance.ANO=Acceptance.LANO    
and Cover.CNO=Acceptance.CNO and Cover.CStatus='A' and Acceptance.AStatus='W'         
and Acceptance.CDate<=AIBucket.Last_Update     
    
go

