--7 NOV 2016 : Perbaikan script R_ACCASS yang digunakan untuk penyajian statistik di mana nilai Gross Premi disesuaikan dengan Porsi dari alokasi sesi ke Reasuransi

if exists (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'R_AccAss') ) BEGIN DROP VIEW dbo.R_AccAss  END
GO
CREATE view R_AccAss                        

as                    

Select A.*          
from                 
(                    
 Select A1.ACNO, A1.ANO, A1.Type, A1.ID, A1.Code, A1.DocNo, A1.RefNo, A1.Date, A1.TOC, A1.PolicyNo, A1.BillDate, A1.Remarks, A1.RCode, A1.AType, A1.NoRefundF, A1.BizmapID, A1.Source, A1.AdmNo, A1.SDate, A1.EDate, R.RDate,                       
 A1.Rate,                   
 A1.Currency_OC, A1.Amount_OC          
 *          
 Case           
 When (A2.AType='A') Then 1
 When (A2.AType='C' and A2.EMethod='A') Then 
 cast(datediff(day,case When A2.pDate<(Case When A1.SDate<A2.PDate then (Case When A2.PDate >A1.EDate Then A1.EDate else A2.PDate end) else A1.SDate end) Then (Case When A1.SDate<A2.PDate then (Case When A2.PDate>A1.EDate Then A1.EDate else A2.PDate end) else A1.SDate end) else Case When A2.pDate>(Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) then (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) else A2.pDate end end, (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end)) as Float)           
 /cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)           
 else           
 cast(datediff(day,case When A2.pDate<(Case When A1.SDate<R.RDate then (Case When R.RDate>A1.EDate Then A1.EDate else R.RDate end) else A1.SDate end) Then (Case When A1.SDate<R.RDate then (Case When R.RDate>A1.EDate Then A1.EDate else R.RDate end) else A1.SDate end) else Case When A2.pDate>(Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) then (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) else A2.pDate end end, (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end)) as Float)           
 /cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)           
 end as Amount_OC,                                   
 A1.Currency, A1.Amount          
 *          
 Case           
 When (A2.AType='A') Then 1
 When (A2.AType='C' and A2.EMethod='A') Then 
 cast(datediff(day,case When A2.pDate<(Case When A1.SDate<A2.PDate then (Case When A2.PDate >A1.EDate Then A1.EDate else A2.PDate end) else A1.SDate end) Then (Case When A1.SDate<A2.PDate then (Case When A2.PDate>A1.EDate Then A1.EDate else A2.PDate end) else A1.SDate end) else Case When A2.pDate>(Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) then (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) else A2.pDate end end, (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end)) as Float)           
 /cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)           
 else           
 cast(datediff(day,case When A2.pDate<(Case When A1.SDate<R.RDate then (Case When R.RDate>A1.EDate Then A1.EDate else R.RDate end) else A1.SDate end) Then (Case When A1.SDate<R.RDate then (Case When R.RDate>A1.EDate Then A1.EDate else R.RDate end) else A1.SDate end) else Case When A2.pDate>(Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) then (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) else A2.pDate end end, (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end)) as Float)           
 /cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)           
 end as Amount                     
 from Accass A1              
 Inner Join Acceptance A2 on (A2.ANO=A1.ANO)             
 Inner Join RArrHeader R on (R.ANO=A2.ANO and A1.CAmount<>0)                                   
 Where cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)<>0                        

 Union All          
           
 Select A1.ACNO, A1.ANO, A1.Type, A1.ID, A1.Code, A1.DocNo, A1.RefNo, A1.Date, A1.TOC, A1.PolicyNo, A1.BillDate, A1.Remarks, A1.RCode, A1.AType, A1.NoRefundF, A1.BizmapID, A1.Source, A1.AdmNo, A1.SDate, A1.EDate, R.RDate,                       
 A1.Rate,                   
 A1.Currency_OC, A1.Amount_OC          
 *          
 Case           
 When (A2.AType='A') Then 1
 When (A2.AType='C' and A2.EMethod='A') Then 
 cast(datediff(day,case When A2.pDate<(Case When A1.SDate<A2.PDate then (Case When A2.PDate>A1.EDate Then A1.EDate else A2.PDate end) else A1.SDate end) Then (Case When A1.SDate<A2.PDate then (Case When A2.PDate>A1.EDate Then A1.EDate else A2.PDate end) else A1.SDate end) else Case When A2.pDate>(Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) then (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) else A2.pDate end end, (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end)) as Float)           
/cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)           
 else           
 cast(datediff(day,case When A2.pDate<(Case When A1.SDate<R.RDate then (Case When R.RDate>A1.EDate Then A1.EDate else R.RDate end) else A1.SDate end) Then (Case When A1.SDate<R.RDate then (Case When R.RDate>A1.EDate Then A1.EDate else R.RDate end) else A1.SDate end) else Case When A2.pDate>(Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) then (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) else A2.pDate end end, (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end)) as Float)           
/cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)           

 end as Amount_OC,                                  
 A1.Currency, A1.Amount          
 *          
 Case           
 When (A2.AType='A') Then 1
 When (A2.AType='C' and A2.EMethod='A') Then
 cast(datediff(day,case When A2.pDate<(Case When A1.SDate<A2.PDate then (Case When A2.PDate>A1.EDate Then A1.EDate else A2.PDate end) else A1.SDate end) Then (Case When A1.SDate<A2.PDate then (Case When A2.PDate>A1.EDate Then A1.EDate else A2.PDate end) else A1.SDate end) else Case When A2.pDate>(Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) then (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) else A2.pDate end end, (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end)) as Float)           
/cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)           
 else           
 cast(datediff(day,case When A2.pDate<(Case When A1.SDate<R.RDate then (Case When R.RDate>A1.EDate Then A1.EDate else R.RDate end) else A1.SDate end) Then (Case When A1.SDate<R.RDate then (Case When R.RDate>A1.EDate Then A1.EDate else R.RDate end) else A1.SDate end) else Case When A2.pDate>(Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) then (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end) else A2.pDate end end, (Case When A1.EDate>R.NRDate then (Case When R.NRDate<A1.SDate Then A1.SDate else R.NRDate end) else A1.EDate end)) as Float)           
 /cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)           
 end as Amount                     
 from Accass A1              
 Inner Join Acceptance A2 on (A2.ANO=A1.ANO)             
 Inner Join RArrHeader R on (R.ANO=A2.pANO and A1.CAmount=0)                                   
 Where cast(datediff(day,case When A2.pDate<A1.SDate Then A1.SDate else Case When A2.pDate>A1.EDate then A1.EDate else A2.pDate end end,A1.EDate) as Float)<>0                                    
) A 

