BEGIN DROP PROCEDURE CLSalvageTo END
GO
CREATE PROCEDURE CLSalvageTo (@P_CNO as integer, @P_Currency as varchar(255))     
AS    
SELECT cno, id, currency, CSType, sum(clSAL.GrossAmount) as GrossAmount, sum(clsal.VAT) as VAT, sum(clsal.amount) AS amount, sum(clsal.TAX) as TAX, sum(clsal.NetAmount) as NetAmount
FROM clsal    
WHERE cno=@p_cno and currency=@p_currency and Status='P'  
GROUP BY cno, id, currency, CSType 
