--Perbaikan Bugs diman jika yang diinforce adalah Fleet Polis maka Fleet Polis tersebut tidak terproses

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'AutoInforce_Process') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN DROP PROCEDURE AutoInforce_Process END
GO
CREATE Procedure AutoInforce_Process(@P_PDate as smalldatetime)                                                

as                                       

--Individual Polis First    

Select AIBucket.ADate, AIBucket.PID, Acceptance.ANO, Acceptance.LANO, Acceptance.RegNo, Acceptance.BatchNo, cast(0 as Bit) as BulkF                  

from AIBucket with (index (I_AIBucket_RegNo_CertificateNo_Last_Update)), Acceptance, Cover                    

where AIBucket.Status='R'     

and Acceptance.RegNo=AIBucket.RegNo and Acceptance.LANO=-1    

and Cover.CNO=Acceptance.CNO and Cover.CStatus='A' and Acceptance.AStatus='W'         

and Acceptance.CDate<=AIBucket.Last_Update     

    

Union All    

    

--Certificate Second    

Select AIBucket.ADate, AIBucket.PID, Acceptance.ANO, Acceptance.LANO, Acceptance.RegNo, Acceptance.BatchNo, cast(0 as Bit) as BulkF    

From AIBucket with (index (I_AIBucket_RegNo_CertificateNo_Last_Update)), Acceptance, Cover                    

where AIBucket.Status='R'     

and Acceptance.RegNo=AIBucket.RegNo and AIBucket.CertificateNo<>'' and Acceptance.CertificateNo=AIBucket.CertificateNo and Acceptance.ANO<>Acceptance.LANO and Cover.OpenFlag=1                  

and Cover.CNO=Acceptance.CNO and Cover.CStatus='A' and Acceptance.AStatus='W'         

and Acceptance.CDate<=AIBucket.Last_Update     

    

Union All    

    

--Bulk Inforce Certificate    

Select AIBucket.ADate, AIBucket.PID, Max(Acceptance.LANO) as ANO, Max(Acceptance.LANO) as LANO, Max(Acceptance.RegNo) as RegNo, Acceptance.BatchNo, cast(1 as Bit) as BulkF                  

from AIBucket with (index (I_AIBucket_RegNo_BatchNo_Last_Update)), Acceptance, Cover                    

where AIBucket.Status='R'     

and Acceptance.RegNo=AIBucket.RegNo and AIBucket.CertificateNo='' and Acceptance.BatchNo=AIBucket.BatchNo and Acceptance.ANO<>Acceptance.LANO and Cover.OpenFlag=1                  

and Cover.CNO=Acceptance.CNO and Cover.CStatus='A' and Acceptance.AStatus='W'         

and Acceptance.CDate<=AIBucket.Last_Update     

Group By AIBucket.ADate, AIBucket.PID, Acceptance.BatchNo    

    

Union All    

    

--Fleet Polis Last    

Select AIBucket.ADate, AIBucket.PID, Acceptance.ANO, Acceptance.LANO, Acceptance.RegNo, Acceptance.BatchNo, cast(0 as Bit) as BulkF    

from AIBucket, Acceptance, Cover                    

where AIBucket.Status='R'     

and Acceptance.RegNo=AIBucket.RegNo and Acceptance.ANO=Acceptance.LANO    

and Cover.CNO=Acceptance.CNO and Cover.CStatus='A' and Acceptance.AStatus='W'         

and Acceptance.CDate<=AIBucket.Last_Update     

    

go

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'PI13') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN DROP PROCEDURE PI13 END
GO
CREATE procedure PI13 (@P_ANO as integer) 
as 
Begin 
Declare @P_Date as smalldatetime 
Declare @P_PolicyNo as varchar(20) 
Declare @P_CertificateNo as varchar(20) 
Declare @P_OpenFLag as Bit 
Declare @P_LANO as int 
Declare @P_A_PolicyNo as varchar(50) 
Select @P_Date = Getdate() 
 
Select @P_LANO=A1.LANO, @P_PolicyNo=A1.PolicyNo, @P_CertificateNo=A1.CertificateNo, @P_OpenFlag=C1.OpenFlag from Acceptance A1, Cover C1 Where C1.CNO=A1.CNO and A1.ANO=@P_ANO 
 
if @P_LANO<>-1 
if @P_OpenFlag=1 and @P_ANO<>@P_LANO 
Select @P_A_PolicyNo=@P_PolicyNo + '-' + @P_CertificateNo 
else 
Select @P_A_PolicyNo=@P_PolicyNo 
else 
Select @P_A_PolicyNo=@P_PolicyNo 
 
Select Admlink.Subject, Voucher.Voucher, Voucher.DueDate, Voucher.DocNo, Voucher_Due.DueDate as NDueDate, 
Profile.Name, Voucher.Currency, 
 
case when Voucher.debtorf=1 then Voucher.Nominal_CC-Voucher.Diff_CC else -(Voucher.Nominal_CC-Voucher.Diff_CC) end  as Nominal, 
case when Voucher.debtorf=1 then (coalesce(Voucher_Due.AmountDue, Voucher.AmountDue)-Voucher.Payment_CC) else -(coalesce(Voucher_Due.AmountDue, Voucher.AmountDue)-Voucher.Payment_CC) end as AmountDue, 
case when Voucher.debtorf=1 then Voucher.Payment_CC else -Voucher.Payment_CC end as Payment, 
case when Voucher.debtorf=1 then Voucher.Nominal_CC-Voucher.Diff_CC - Voucher.Payment_CC else -(Voucher.Nominal_CC-Voucher.Diff_CC - Voucher.Payment_CC) end as Outstanding 
 
from nVoucher Voucher Left Join Voucher_AmountDue(@P_Date) Voucher_Due on (Voucher_Due.Voucher=Voucher.Voucher), Profile, ProAcc, Admlink 
Where Profile.ID=ProAcc.ID and ProAcc.ProAcc=Voucher.ProAcc and Admlink.Voucher=Voucher.Voucher 
and Admlink.Type in ('DI','IC','IR','CF','JP','BB','BA','BO','OP','FO') 
and Admlink.A_PolicyNo<>'' and Admlink.A_PolicyNo=@P_A_PolicyNo and (Admlink.Extra_1='' or Admlink.Extra_1 is null) 
 
end 
 
 

go


