/****** Object:  TABLE GENDSEGMENT    Script Date: 10/17/2016 15:01:28 ******/
IF  NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'GENDSEGMENT') AND type in (N'U'))
BEGIN
CREATE TABLE GENDSEGMENT(
	FLDID varchar(10) NOT NULL,
	VALUEID varchar(15) NOT NULL,
	SEGMENT varchar(10) NOT NULL,
 CONSTRAINT I_GENDSEGMENT PRIMARY KEY CLUSTERED 
(
	FLDID ASC,
	VALUEID ASC,
	SEGMENT ASC
)WITH (PAD_INDEX  = OFF, STATISTICS_NORECOMPUTE  = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS  = ON, ALLOW_PAGE_LOCKS  = ON) ON [PRIMARY]
) ON [PRIMARY]
EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Field ID (see GenHTab)' , @level0type=N'SCHEMA',@level0name=N'dbo', @level1type=N'TABLE',@level1name=N'GENDSEGMENT', @level2type=N'COLUMN',@level2name=N'FLDID'
