IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'FN_GENDTAB') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) )
BEGIN DROP FUNCTION FN_GENDTAB END
GO   
CREATE FUNCTION FN_GENDTAB (@P_TOC as varchar(10),@P_SEGMENT as varchar(10))   
RETURNS TABLE   
as RETURN(   
Select G1.*   
from GenDTab G1 Inner Join GenHTab G2 on (G2.FLDID=G1.FLDID)   
Where   
(   
G2.SubClassF=0 or @P_TOC=''   
or (G2.SubClassF=1 and EXISTS (Select Top 1 ValueID from GenDTOC G3 Where G3.FLDID=G1.FLDID and G3.VALUEID=G1.VALUEID and (G3.TOC='<All>' or G3.TOC=@P_TOC)))   
)
and    
(   
G2.SegmentF=0 or @P_SEGMENT=''   
or (G2.SegmentF=1 and EXISTS (Select Top 1 ValueID from GenDSegment G3 Where G3.FLDID=G1.FLDID and G3.VALUEID=G1.VALUEID and (G3.SEGMENT='<All>' or G3.SEGMENT=@P_SEGMENT)))   
)
)   
GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QACCDOCLIST') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
BEGIN DROP PROCEDURE QACCDOCLIST END
GO
CREATE Procedure QACCDOCLIST(@P_ANO integer)   
as   
Select A1.*, A2.ImageID   
from   
(   
select Cast(coalesce(ACCDOCLIST.AvailableF, 0) as bit) as ProcessFlag, PDOCLIST.DocType, coalesce(ACCDOCLIST.Description, PDOCLIST.Description) as Description, coalesce(ACCDOCLIST.AvailableF, 0) as AvailableF, cast(coalesce(DOCTYPE.CollectionF,0) as Bit) 
as CollectionF, ACCDOCLIST.RECDATE   
from ACCEPTANCE INNER JOIN COVER ON (ACCEPTANCE.ANO=@P_ANO AND COVER.CNO=ACCEPTANCE.CNO) INNER JOIN PDOCLIST ON (PDOCLIST.TOC=COVER.TOC) Left join DOCTYPE on (DOCTYPE.DOCTYPE=PDOCLIST.DOCTYPE)   
Left Join ACCDOCLIST on (ACCDOCLIST.ANO=@P_ANO and ACCDOCLIST.DOCTYPE=PDOCLIST.DOCTYPE)   
   
Union All   
   
select Cast(coalesce(ACCDOCLIST.AvailableF, 0) as bit) as ProcessFlag, ACCDOCLIST.DocType, ACCDOCLIST.Description, ACCDOCLIST.AvailableF, cast(coalesce(DOCTYPE.CollectionF,0) as Bit) as CollectionF, ACCDOCLIST.RECDATE   
from ACCDOCLIST Left Join DOCTYPE on (DOCTYPE.DOCTYPE=ACCDOCLIST.DOCTYPE)   
Where ACCDOCLIST.ANO=@P_ANO   
AND NOT EXISTS (Select PDOCLIST.DOCTYPE from PDOCLIST, COVER, ACCEPTANCE Where PDOCLIST.DOCTYPE=ACCDOCLIST.DOCTYPE AND ACCEPTANCE.ANO=@P_ANO AND COVER.CNO=ACCEPTANCE.CNO AND PDOCLIST.TOC=COVER.TOC)   
) A1 Left Join ACCDOCLISTPIC A2 on (A2.ANO=@P_ANO and A2.DocType=A1.DocType)
Order By A1.DOCTYPE   
GO

