CREATE Procedure QCheck_LinkBatchNo(@BatchNo as varchar(20), @ContractNo as varchar(50),@ORDERNO AS varchar(50),@DOCNO AS varchar(50)) 
as 
Select Top 1 BatchNo, ContractNo
from SysBatchSC S2
Where S2.BatchNo=@BatchNo and S2.ContractNo=@ContractNo and S2.ORDERNO=@ORDERNO and S2.DOCNO=@DOCNO 
and S2.Status='N' and S2.ErrMsg Not Like 'On-Progress%'

Union All

Select Top 1 BatchNo, ContractNo
from SysBatchOriginalSC S2
Where S2.BatchNo=@BatchNo and S2.ContractNo=@ContractNo and S2.ORDERNO=@ORDERNO and S2.DOCNO=@DOCNO 
and S2.Status='N' and S2.ErrMsg Not Like 'On-Progress%'
go

