IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'PCALC01') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE PCALC01 END
GO   
CREATE Procedure PCALC01(@P_ANO integer)    
As    
SELECT  COVER.TOC,    
  COVER.PPERIOD,    
  COVER.PRORATA,    
  COVER.VOYAGE,    
  RCOVER.UNIT,    
  RCOVER.CODE,    
  RATECOV.TOR,    
  RCOVER.DISCOUNT,    
  RCOVER.LOADING,    
  RCOVER.RATE*RATECOV.PORTION/RCOVER.PORTION AS RATE,    
  RATECOV.PORTION,    
  RCOVER.SDATE,    
  RCOVER.EDATE,    
  RCOVER.PCALC,    
  Case WHEN ICOVER.NOTDECRF=1 OR ICOVER.NOTFLF=1 then 100 else RCOVER.PCTLOSS end as PCTLOSS,    
  Case WHEN ICOVER.NOTDECRF=1 OR ICOVER.NOTFLF=1 then 0 else RCOVER.PADDITION end as PADDITION,    
  CASE WHEN ICOVER.NOTFLF=1 THEN 100 ELSE RCOVER.PPRORATA END AS PPRORATA,
  ICOVER.CURRENCY,    
  ICOVER.SI,    
  ICOVER.INDEMNITY,    
  (Select sum(DDiscount) from AccDed Where ANO=ICover.ANO and Currency=ICover.Currency and TOR=RateCov.TOR) as DDISCOUNT,
  ICOVER.Adjustable,    
  ICOVER.PCTADJ,    
  ICOVER.INO,    
  ACCEPTANCE.ANO as SANO,    
  PolicyType.SType
FROM  RCLASS, RATECOV, RCOVER, PCLASS, ICOVER, TOI, ACCEPTANCE, COVER Left Join PolicyType on (PolicyType.PolicyType=Cover.PolicyType)    
WHERE  ACCEPTANCE.ANO=@P_ANO    
  And COVER.CNO=ACCEPTANCE.CNO    
  And RCLASS.TOC=COVER.TOC    
  And RCOVER.ANO=ACCEPTANCE.ANO    
  And ICOVER.ANO=ACCEPTANCE.ANO    
  And RATECOV.CODE=RCOVER.CODE    
  And RCLASS.TOR=RATECOV.TOR    
  And PCLASS.TOR=RATECOV.TOR    
  And PCLASS.TOI=ICOVER.TOI    
  And TOI.TOI=ICOVER.TOI    
ORDER BY ICOVER.CURRENCY, RCOVER.CODE, RATECOV.TOR,RCOVER.SDATE, ACCEPTANCE.ANO
  
GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'PCALC01_ADJ') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE PCALC01_ADJ END
GO
CREATE Procedure PCALC01_ADJ(@P_ANO integer)   
As   
SELECT  COVER.TOC,   
COVER.PPERIOD,   
DATEDIFF(DAY,A1.SDATE, A1.EDATE) as PRORATA,   
COVER.VOYAGE,   
RCOVER.UNIT,   
RCOVER.CODE,   
RATECOV.TOR,   
RCOVER.DISCOUNT,   
RCOVER.LOADING,   
RCOVER.RATE*RATECOV.PORTION/RCOVER.PORTION*RCalc.Prorata AS RATE,   
RATECOV.PORTION,   
   
case   
when RCOVER.SDATE<A2.PDATE then A2.PDATE   
Else RCOVER.SDATE end as SDATE,   
Case   
When RCOVER.EDATE>A2.PPDATE then A2.PPDATE   
ELSE RCOVER.EDATE end as EDATE,   
Case WHEN ICOVER.NOTDECRF=1 then 100 else RCOVER.PCTLOSS end as PCTLOSS,   
Case WHEN ICOVER.NOTDECRF=1 then 0 else RCOVER.PADDITION end as PADDITION,   
Case When (Case when RCOVER.SDATE<A2.PDATE then A2.PDATE Else RCOVER.SDATE end)=A1.SDATE 
AND (Case When RCOVER.EDATE>A2.PPDATE then A2.PPDATE ELSE RCOVER.EDATE end)=A1.EDATE Then RCover.PCalc Else 'P' End as PCalc,   
Case when TOI.ADJMETHOD='OVERLIMIT ' then A1.CPCT else (Case When A1.CPCT<>0 then A1.CPCT else 100 end*cast(datediff(day, case when RCOVER.SDATE<A2.PDATE then A2.PDATE Else RCOVER.SDATE end, Case When RCOVER.EDATE>A2.PPDATE then A2.PPDATE ELSE RCOVER.EDATE end) as float)/  cast(DATEDIFF(DAY,A1.SDATE, A1.EDATE) as float)) end as PPRORATA,   
ICOVER.CURRENCY,   
ICOVER.SI,   
(Select sum(DDiscount) from AccDed Where ANO=ICover.ANO and Currency=ICover.Currency and TOR=RateCov.TOR) as DDISCOUNT,
ICOVER.Adjustable,   
ICOVER.PCTADJ,   
TOI.ADJMETHOD,   
ICOVER.INO,   
A2.ANO AS SANO,   
PolicyType.SType   
FROM  RCLASS, RATECOV, RCOVER, PCLASS, ICOVER, TOI, RCalc, COVER Left Join PolicyType on (PolicyType.PolicyType=Cover.PolicyType), ACCEPTANCE A1, ACCEPTANCE A2   
Where A1.PDate <= A2.PDate And A1.PPDate >= A2.PPDate And A2.PDate <= A2.PPDate   
and A1.ANO=@P_ANO and A2.OANO=A1.OANO and A2.ANO<=A1.PANO and A2.ANO<@P_ANO and A2.AType not in ('A','C') and Cover.CNO=A1.CNO   
and ICOVER.ANO=A1.ANO and ICOVER.Adjustable=1   
and RCOVER.ANO=A2.ANO   
and RATECOV.CODE=RCOVER.CODE   
and RCLASS.TOC=COVER.TOC   
and RCLASS.TOR=RATECOV.TOR   
and PCLASS.TOR=RATECOV.TOR   
and PCLASS.TOI=ICOVER.TOI   
and TOI.TOI=ICOVER.TOI   
and RCalc.ANO=A2.ANO and RCalc.Currency=ICover.Currency and RCalc.Code=RCover.Code and RCalc.TOR=RateCov.TOR and RCalc.SDate=RCover.SDate   
and NOT EXISTS (Select PANO from Acceptance A3 Where A3.PANO=A2.ANO and A3.AStatus<>'C' and A3.AType='A' and A3.ANO<>@P_ANO)   
and (TOI.ADJMETHOD<>'OVERLIMIT' or A2.ANO=A1.PANO)   
ORDER BY ICOVER.CURRENCY, RCOVER.CODE, RATECOV.TOR, RCOVER.SDATE, A2.ANO   
   
GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'PCALC02A') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE PCALC02A END
GO
CREATE Procedure PCALC02A (@P_ANO integer,@P_CURRENCY varchar(10))
As
SELECT SUM(RCALC.GROSS) AS PREMIUM, SUM(RCALC.OGROSS) AS OPREMIUM, SUM(RCALC.DISCOUNT) AS DISCOUNT, SUM(RCALC.DDISCOUNT) AS DDISCOUNT
FROM RCALC
WHERE RCALC.ANO=@P_ANO And RCALC.CURRENCY=@P_CURRENCY

go

