--30 nov 2016
if exists (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'Get_Open_Item_P') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) BEGIN DROP FUNCTION Get_Open_Item_P END
GO
CREATE function Get_Open_Item_P (@P_Voucher Varchar(20))      
RETURNS Table      
AS RETURN      
(      
 Select SL.Voucher, SL.Account, SL.Description, SL.Branch, Max(SL.Hint) as Hint, sum(SL.Nominal_OC) as Nominal_OC      
  From      
   (      
 --Part Of OSL Functions
          
 Select pSL.Voucher, Account.Account, Account.Description, pSL.Branch, pSL.Hint, pSL.Nominal as Nominal_OC
 from pSLSUM pSL
 Inner Join Account on (Account.Account=pSL.Account and Account.Suspend_Flag=1)
 Where (pSL.Voucher=@P_Voucher or @P_Voucher='') 
                                               
 Union All      
                          
 select pVoucher.Voucher, SL.SAccount Account, Account.Description, Voucher.Branch, SL.Hint, SL.Nominal as Nominal_OC 
 from pVoucher pVoucher, pVoucher Voucher, pSL SL, Account      
 Where (pVoucher.Voucher=@P_Voucher or @P_Voucher='') and pVoucher.SL_Cat='P'    
 and Voucher.RefNo=pVoucher.Voucher and Voucher.SL_Cat='A'      
 and SL.Voucher=Voucher.Voucher and Account.Account=SL.SAccount and Account.Suspend_Flag=1      
                          
 Union All      
 
 select pVoucher.Voucher, SL.SAccount as Account, Account.Description, Voucher.Branch, SL.Hint, SL.Nominal as Nominal_OC 
 from pVoucher pVoucher, pVoucher OVoucher, pVoucher Voucher, pSL SL, Account      
 Where (pVoucher.Voucher=@P_Voucher or @P_Voucher='') and pVoucher.SL_Cat='P'    
 and OVoucher.RefNo=pVoucher.Voucher and OVoucher.SL_Cat='B'      
 and Voucher.RefNo=OVoucher.Voucher and Voucher.SL_Cat='A' and SL.Voucher=Voucher.Voucher and Account.Account=SL.SAccount and Account.Suspend_Flag=1      
 
 ) SL      

 Group By SL.Voucher, SL.Account, SL.Description, SL.Branch 
 --having sum(SL.Nominal_OC)<>0      

)      
GO

if exists (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'OPEN_ITEM_ALLOCATED') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) BEGIN DROP FUNCTION OPEN_ITEM_ALLOCATED END
GO
CREATE FUNCTION OPEN_ITEM_ALLOCATED(@P_VOUCHER VARCHAR(20)) 
RETURNS TABLE  AS 
RETURN ( 
--SL from Payment Voucher 
Select pSL.Voucher, pVoucher.Branch, pVoucher.Date as Doc_Date, pVoucher.Currency as Doc_CCY, pSL.Voucher as Doc_No, pSL.Account, pSL.Account as PAccount, 1 as PaymentF, 1 as Rate, sum(pSL.Rate*pSL.Nominal_OC) as Nominal_OC 
From dbo.pSL 
Inner Join dbo.pVoucher on (pVoucher.Voucher=pSL.Voucher) 
Where pVoucher.SL_Cat in ('P') and pSL.PaymentF=1 
and (pVoucher.Voucher=@P_Voucher or @P_Voucher='') 
Group By pSL.Voucher, pVoucher.Date, pVoucher.Branch, pVoucher.Currency, pSL.Account 

Union All 

--SL from InterOffice Overbooking Voucher 
Select pVoucher.RefNo as Voucher, pVoucher.Branch, pVoucher.Date as Doc_Date, pVoucher.Currency as Doc_CCY, pVoucher.RefNo as Doc_No, pSL.Account, pSL.Account as PAccount, 1 as PaymentF, 1 as Rate, sum(pSL.Rate*pSL.Nominal_OC) as Nominal_OC 
From dbo.pSL 
Inner Join dbo.pVoucher on (pVoucher.Voucher=pSL.Voucher) 
Inner Join dbo.pVoucher OVoucher on (OVoucher.Voucher=pVoucher.RefNo) 
Where pVoucher.SL_Cat in ('B') and pVoucher.RefType='INTEROFFICE' and pSL.PaymentF=1 
and (pVoucher.RefNo=@P_Voucher or @P_Voucher='') 
Group By pVoucher.RefNo, pVoucher.Date, pVoucher.Branch, pVoucher.Currency, pSL.Account 

Union All
 
--SL from Overbooking Payment and Adjustment Payment 
Select SL.Voucher, VoucherR.Branch, VoucherR.Date as Doc_Date, VoucherR.Currency as Doc_CCY, VoucherP.Voucher as Doc_No, SL.SAccount as Account, SL.Account as PAccount, 1 as PaymentF, 1 as Rate, 
sum((case When VoucherR.DebtorF=VoucherP.DebtorF Then SL.Nominal_OC else -SL.Nominal_OC end*SL.Rate)) as Nominal_OC 
from pSL SL, pVoucher VoucherP, pVoucher VoucherR 
Where VoucherR.RefType<>'INTEROFFICE' and VoucherR.SL_Cat in ('B') and VoucherP.SL_Cat='P' and VoucherR.RefNo=VoucherP.Voucher and SL.Voucher=VoucherR.Voucher and SL.PaymentF=1 
and (VoucherP.Voucher=@P_Voucher or @P_Voucher='') 
Group By SL.Voucher, VoucherR.Date, VoucherR.Branch, VoucherR.Currency, VoucherP.Voucher, SL.SAccount, SL.Account 
 
Union All 

--SL from Sub Ledger Payment Voucher and OverPaid 
Select SL.Voucher, VoucherR.Branch, SL.Doc_Date, SL.Doc_CCY, SL.Doc_No as Doc_No, SL.Account, SL.Account as PAccount, 1 as PaymentF, 1 as Rate, 
(Case When VoucherR.SL_Cat='O' 
then (case when VoucherR.DebtorF=VoucherP.DebtorF then SL.Nominal_OC else -SL.Nominal_OC end) 
else (case when VoucherR.DebtorF<>VoucherP.DebtorF then SL.Nominal_OC else -SL.Nominal_OC end) 
end) as Nominal_OC 
from pSL SL, pVoucher VoucherP, pVoucher VoucherR 
Where VoucherR.SL_Cat in ('O','P','A','B') and VoucherP.SL_Cat='P' and VoucherR.Voucher=SL.Voucher and SL.Doc_No=VoucherP.Voucher and SL.PaymentF=1 
and (VoucherP.Voucher=@P_Voucher or @P_Voucher='') 
) 
go

--31 jan 2017
IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QREINSURANCE_CESSION') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE QREINSURANCE_CESSION END
GO
CREATE Procedure QREINSURANCE_CESSION (@P_ANO integer, @P_ADate smalldatetime, @P_RType varchar(255), @P_TSI Float=0, @P_RID varchar(20)='', @P_ManualF Bit=0, @P_GROSS Float=0)                                
as                                                          
SELECT (Case When ReClass.PriorityF=1 Then ReClass.PriorityF else Reinsurance.PriorityF end) as PriorityF, Reinsurance.RID, Reinsurance.RType,                                
ReClass.PLimit, Case RECLASS.Limit WHEN 0 then Reinsurance.Limit Else RECLASS.Limit end as limit, ReClass.ShortFallLimit,              
ReClass.MinTSI, Reinsurance.UjrohReins, Reinsurance.UjrohCedant, Reinsurance.Share, Reinsurance.PShare, Acceptance.FLDID, Acceptance.ValueID, ReClass.CessionF, ReClass.AssessmentF, ReClass.DirectF                                
From Acceptance       
Inner Join Cover on (Cover.CNO=Acceptance.CNO)      
Left Join RArrHeader on (RArrHeader.ANO=Acceptance.ANO)      
Inner Join Reinsurance on (Reinsurance.RType=@P_RType)      
Inner Join ReClass on (ReClass.RNO=Reinsurance.RNO and ReClass.TOC=Cover.TOC)      
Left Join RePolicy on (RePolicy.RNO=Reinsurance.RNO)      
WHERE ACCEPTANCE.ANO=@P_ANO         
And Case When Reinsurance.PolicyRunOffF=1 Then Acceptance.SDate else @P_ADATE end Between Reinsurance.SDate And Reinsurance.EDate         
And (@P_RID='' or Reinsurance.RID=@P_RID or RArrHeader.ManualF=0 or Acceptance.EMethod='T')                            
And (coalesce(RePolicy.ID,'')='' or  coalesce(RePolicy.ID,'')=Cover.PHolder)    
And (@P_ManualF=1 or RArrHeader.ManualF=1 or       
(      
 (Reinsurance.ORBusinessF=RArrHeader.ORBusinessF)      
 And (@P_TSI>=ReClass.MinTSI or ReClass.MinTSI=0) and (@P_TSI<=ReClass.MaxTSI or ReClass.MaxTSI=0) and (@P_GROSS>=ReClass.MinGross or ReClass.MinGross=0) and (@P_GROSS<=ReClass.MaxGross or ReClass.MaxGross=0)                 
 And (    
 (datediff(month, Case When Reinsurance.PolicyRunOffF=1 then Acceptance.SDate else coalesce(RArrHeader.RDate,acceptance.sdate) end, Case When Reinsurance.PolicyRunOffF=1 then Acceptance.EDate else coalesce(RArrHeader.NRDate,Acceptance.EDate) end)>=ReClass.MinPeriod)     
 or (datediff(month, Case When Reinsurance.PolicyRunOffF=1 then Acceptance.SDate else coalesce(RArrHeader.RDate,acceptance.sdate) end, Case When Reinsurance.PolicyRunOffF=1 then Acceptance.EDate else coalesce(RArrHeader.NRDate,Acceptance.EDate) end)=ReClass.MinPeriod-1 and day(Case When Reinsurance.PolicyRunOffF=1 then Acceptance.SDate else coalesce(RArrHeader.RDate,acceptance.sdate) end)<day(Case When Reinsurance.PolicyRunOffF=1 then Acceptance.EDate else coalesce(RArrHeader.NRDate,Acceptance.EDate) end))     
 or ReClass.MinPeriod=0)                               
 And (    
 (datediff(month, Case When Reinsurance.PolicyRunOffF=1 then Acceptance.SDate else coalesce(RArrHeader.RDate,acceptance.sdate) end, Case When Reinsurance.PolicyRunOffF=1 then Acceptance.EDate else coalesce(RArrHeader.NRDate,Acceptance.EDate) end)<ReClass.MaxPeriod)     
 or (datediff(month, Case When Reinsurance.PolicyRunOffF=1 then Acceptance.SDate else coalesce(RArrHeader.RDate,acceptance.sdate) end, Case When Reinsurance.PolicyRunOffF=1 then Acceptance.EDate else coalesce(RArrHeader.NRDate,Acceptance.EDate) end)=ReClass.MaxPeriod and day(Case When Reinsurance.PolicyRunOffF=1 then Acceptance.SDate else coalesce(RArrHeader.RDate,acceptance.sdate) end)>=day(Case When Reinsurance.PolicyRunOffF=1 then Acceptance.EDate else coalesce(RArrHeader.NRDate,Acceptance.EDate) end))     
 or ReClass.MaxPeriod=0))      
)                    
And Exists (Select Top 1 RCalc.ANO from RCalc Left Join RPartDet on (RPartDet.RNO=Reinsurance.RNO and RPartDet.TOR=RCalc.TOR) Where RCalc.ANO=Acceptance.ANO and coalesce(RPartDet.ExcludeF,0)=0)  
Order By coalesce(RePolicy.ID,'') Desc, (Case When ReClass.PriorityF=1 Then ReClass.PriorityF else Reinsurance.PriorityF end) Desc                   
 go


--1 February 2017
IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'Get_Open_Item_N') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) BEGIN DROP FUNCTION Get_Open_Item_N END
GO
CREATE function Get_Open_Item_N (@P_Voucher Varchar(20))      
RETURNS Table      
AS RETURN      
(      
 Select Top 1 Voucher.Voucher, Account.Account, Account.Description, Voucher.Branch, Voucher.CT, SL.Hint, Case When Voucher.DebtorF=1 Then (Voucher.Nominal_CC-Voucher.Diff_CC) else -(Voucher.Nominal_CC-Voucher.Diff_CC) end as Nominal_OC      
 from nVoucher Voucher inner Join nSL SL on (SL.Voucher=Voucher.Voucher) inner Join Account on (Account.Account=SL.Account and Account.Open_ItemF=1)      
 Where Voucher.Voucher=@P_Voucher      
 and Voucher.SL_Tag=0	-- Not Manual Voucher
 order by SL.hint Desc
)                  
GO

IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'Get_Open_Item_M') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) BEGIN DROP FUNCTION Get_Open_Item_M END
GO
CREATE function Get_Open_Item_M (@P_Voucher Varchar(20))  
RETURNS Table  
AS RETURN  
(  
 Select Voucher.Voucher, Account.Account, Account.Description, Max(Voucher.Branch) as Branch, Max(Voucher.CT) as CT, Max(SL.Hint) as Hint, sum(Case When Voucher.DebtorF=1 Then SL.Nominal else -SL.Nominal end) as Nominal_OC  
 from nVoucher Voucher, nSL SL, VType, VPattern, Account  
 Where Voucher.Voucher=@P_Voucher and Voucher.InvestmentF=0 and Vtype.TaxF=0 and Voucher.Voucher=SL.Voucher 
 and VType.VType=Voucher.VType and VPattern.VType=VType.VType 
 and (VPattern.Debit=SL.Hint or VPattern.Credit=SL.Hint) and Account.Account=VPattern.Account and Account.Open_ItemF=1  
 and Voucher.SL_Tag=1	-- Manual Voucher
 Group by Voucher.Voucher, Account.Account, Account.Description  
)  
GO

--Update Script - VAT_IN_PROCESS DAN VAT_OUT_PROCESS

IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'VAT_IN_PROCESS') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) BEGIN DROP FUNCTION VAT_IN_PROCESS END
GO
CREATE FUNCTION VAT_IN_PROCESS(@P_Type varchar(2),@P_Date smalldatetime, @P_PEDate smalldatetime,@P_EDate smalldatetime)                            
RETURNS TABLE                            
AS RETURN(                            
select A.Branch, A.DocNo, A.RefNo, @P_Date as Date, A.Code as Code, @P_Type as Type, SysTab.Currency, 'JOURNAL' as Subject, A.Remarks as Remarks,
 'Amount_1'  = 0,
 'Amount_2'  = Case When (A.Subject='Premium' and A.Type in ('BB','BA','BC','BO','OP')) then dbo.fn_SL_Payment_Nominal(SL.Nominal_OC, pVoucher.SL_Cat, pVoucher.DebtorF, V.DebtorF)*A.Amount_13/A.Amount*V.Rate else 0 end,
 'Amount_3'  = Case When (A.Subject='Premium' and A.Type in ('DC','XP','CP','QS','QP','S1','S2','S3','AF','FO')) then dbo.fn_SL_Payment_Nominal(SL.Nominal_OC, pVoucher.SL_Cat, pVoucher.DebtorF, V.DebtorF)*A.Amount_13/A.Amount*V.Rate else 0 end,
 'Amount_4'  = 0,                       
 'Amount_5'  = Case When (A.Subject='Claim' and A.Type in ('DI','IC','IR','IT','IX')) or (A.Subject='Claim' and A.Type in ('OP') and A.Amount_9<>0) then dbo.fn_SL_Payment_Nominal(SL.Nominal_OC, pVoucher.SL_Cat, pVoucher.DebtorF, V.DebtorF)*A.Amount_13/A.Amount*V.Rate else 0 end,
 'Amount'    = dbo.fn_SL_Payment_Nominal(SL.Nominal_OC, pVoucher.SL_Cat, pVoucher.DebtorF, V.DebtorF)*A.Amount_13/A.Amount*V.Rate
from pSL SL, pVoucher, nVoucher V, Admlink A, SysTab
where A.Voucher=V.Voucher and pVoucher.Voucher=SL.Voucher and V.Voucher=SL.Doc_No and SL.PaymentF=1 and V.SL_Cat='N' 
and pVoucher.Date>@P_PEDate and pVoucher.Date<=@P_EDate
and A.Amount_13<>0
and (
(A.Subject='Premium' and A.Type in ('BB','BA','BC','BO','OP')) or
(A.Subject='Premium' and A.Type in ('DC','XP','CP','QS','QP','S1','S2','S3','AF','FO')) or
(A.Subject='Claim' and A.Type in ('DI','IC','IR','IT','IX')) or -- Claim Loss
(A.Subject='Claim' and A.Type in ('OP') and A.Amount_9<>0)	-- Claim Expenses
)
)                            
GO

IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'VAT_OUT_PROCESS') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) BEGIN DROP FUNCTION VAT_OUT_PROCESS END
GO
CREATE FUNCTION VAT_OUT_PROCESS(@P_Type varchar(2),@P_Date smalldatetime, @P_PEDate smalldatetime,@P_EDate smalldatetime)                            
RETURNS TABLE                            
AS RETURN(                            
select A.Branch, A.DocNo, A.RefNo, @P_Date as Date, A.Code as Code, @P_Type as Type, SysTab.Currency, 'JOURNAL' as Subject, A.Remarks as Remarks,
 'Amount_1'  = Case When (A.Subject='Premium' and A.Type in ('DI','IC','IR','IT','IX')) Then A.Amount_13*V.Rate else 0 end,
 'Amount_2'  = 0,
 'Amount_3'  = 0,                       
 'Amount_4'  = Case When (A.Subject='Claim' and A.Type in ('OP') and A.Amount_8<>0) Then A.Amount_13*V.Rate else 0 end,
 'Amount_5'  = 0,                       
 'Amount'    = A.Amount_13*V.Rate
from nVoucher V, Admlink A, SysTab
where A.Voucher=V.Voucher 
and coalesce(V.TaxNo,'')<>'' and V.TaxDate>@P_PEDate and V.TaxDate<=@P_EDate
and A.Amount_13<>0
and (
(A.Subject='Premium' and A.Type in ('DI','IC','IR','IT','IX')) or
(A.Subject='Claim' and A.Type in ('OP') and A.Amount_8<>0)	-- Claim Salvage
)
)                            
GO


