IF NOT EXISTS (SELECT * FROM SYS.EXTENDED_PROPERTIES WHERE major_id = OBJECT_ID('Scheme_Additional') AND name = N'MS_Description' AND minor_id = (SELECT column_id FROM SYS.COLUMNS WHERE name = 'ProgressiveF' AND object_id = OBJECT_ID('Scheme_Additional')))
