--28 February 2017 (2)
IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'fn_Rate_Loading') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) BEGIN DROP FUNCTION fn_Rate_Loading END
GO
Create Function fn_Rate_Loading(@P_ANO as int)    
RETURNS Float
AS    
BEGIN    
 Declare @Rate  as Float
 Declare @TotalRate as Float
      
 Select @TotalRate=1
 DECLARE RCover_Cursor CURSOR FOR    
 Select R1.Rate
 from RCover R1
 Where R1.ANO=@P_ANO and R1.Unit='L'
 
 OPEN RCover_Cursor    
 FETCH FROM RCover_Cursor into @Rate
 WHILE @@FETCH_STATUS = 0    
 BEGIN    
	Select @TotalRate=@TotalRate*(1+@Rate)
    FETCH NEXT FROM RCover_Cursor into @Rate
 End    
 Close RCover_Cursor    
 Deallocate RCover_Cursor    
 Return (@TotalRate)    
End    
GO

DROP Procedure PCALC01
GO
CREATE Procedure PCALC01(@P_ANO integer)    
As    
SELECT  COVER.TOC,    
  COVER.PPERIOD,    
  COVER.PRORATA,    
  COVER.VOYAGE,    
  CASE WHEN RCOVER.UNIT='L' Then 'C' ELSE RCOVER.UNIT END AS UNIT,    
  RCOVER.CODE,    
  RATECOV.TOR,    
  RCOVER.DISCOUNT+RCOVER.DISCOUNT_EXT AS DISCOUNT,    
  RCOVER.LOADING,    
  CASE 
  WHEN RCOVER.UNIT='L' Then 0 
  WHEN RCOVER.CATEGORY='M' AND ICOVER.CATEGORY='M' THEN RCOVER.RATE*RATECOV.PORTION/RCOVER.PORTION*DBO.FN_RATE_LOADING(RCOVER.ANO)
  ELSE RCOVER.RATE*RATECOV.PORTION/RCOVER.PORTION
  END AS RATE,
  RATECOV.PORTION,    
  RCOVER.SDATE,    
  RCOVER.EDATE,    
  RCOVER.PCALC,    
  Case WHEN ICOVER.NOTDECRF=1 OR ICOVER.NOTFLF=1 then 100 else RCOVER.PCTLOSS end as PCTLOSS,    
  Case WHEN ICOVER.NOTDECRF=1 OR ICOVER.NOTFLF=1 then 0 else RCOVER.PADDITION end as PADDITION,    
  CASE WHEN ICOVER.NOTFLF=1 THEN 100 ELSE RCOVER.PPRORATA END AS PPRORATA,
  ICOVER.CURRENCY,    
  ICOVER.SI,    
  ICOVER.INDEMNITY,    
  (Select sum(DDiscount) from AccDed Where ANO=ICover.ANO and Currency=ICover.Currency and TOR=RateCov.TOR) as DDISCOUNT,
  ICOVER.Adjustable,    
  ICOVER.PCTADJ,    
  ICOVER.INO,    
  ACCEPTANCE.ANO as SANO,    
  PolicyType.SType
FROM  RCLASS, RATECOV, RCOVER, PCLASS, ICOVER, TOI, ACCEPTANCE, COVER Left Join PolicyType on (PolicyType.PolicyType=Cover.PolicyType)    
WHERE  ACCEPTANCE.ANO=@P_ANO    
  And COVER.CNO=ACCEPTANCE.CNO    
  And RCLASS.TOC=COVER.TOC    
  And RCOVER.ANO=ACCEPTANCE.ANO    
  And ICOVER.ANO=ACCEPTANCE.ANO    
  And RATECOV.CODE=RCOVER.CODE    
  And RCLASS.TOR=RATECOV.TOR    
  And PCLASS.TOR=RATECOV.TOR    
  And PCLASS.TOI=ICOVER.TOI    
  And TOI.TOI=ICOVER.TOI    
ORDER BY ICOVER.CURRENCY, RCOVER.CODE, RATECOV.TOR,RCOVER.SDATE, ACCEPTANCE.ANO
GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'PCALC01_ADJ') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE PCALC01_ADJ END
GO
CREATE Procedure PCALC01_ADJ(@P_ANO integer)   
As   
SELECT  COVER.TOC,   
COVER.PPERIOD,   
DATEDIFF(DAY,A1.SDATE, A1.EDATE) as PRORATA,   
COVER.VOYAGE,   
CASE WHEN RCOVER.UNIT='L' Then 'C' ELSE RCOVER.UNIT END AS UNIT,    
RCOVER.CODE,   
RATECOV.TOR,   
RCOVER.DISCOUNT+RCOVER.DISCOUNT_EXT AS DISCOUNT,    
RCOVER.LOADING,   
CASE 
WHEN RCOVER.UNIT='L' Then 0 
WHEN RCOVER.CATEGORY='M' AND ICOVER.CATEGORY='M' THEN RCOVER.RATE*RATECOV.PORTION/RCOVER.PORTION*RCalc.Prorata*DBO.FN_RATE_LOADING(RCOVER.ANO)
ELSE RCOVER.RATE*RATECOV.PORTION/RCOVER.PORTION*RCalc.Prorata
END AS RATE,   
case   
when RCOVER.SDATE<A2.PDATE then A2.PDATE   
Else RCOVER.SDATE end as SDATE,   
Case   
When RCOVER.EDATE>A2.PPDATE then A2.PPDATE   
ELSE RCOVER.EDATE end as EDATE,   
Case WHEN ICOVER.NOTDECRF=1 then 100 else RCOVER.PCTLOSS end as PCTLOSS,   
Case WHEN ICOVER.NOTDECRF=1 then 0 else RCOVER.PADDITION end as PADDITION,   
Case When (Case when RCOVER.SDATE<A2.PDATE then A2.PDATE Else RCOVER.SDATE end)=A1.SDATE AND (Case When RCOVER.EDATE>A2.PPDATE then A2.PPDATE ELSE RCOVER.EDATE end)=A1.EDATE Then RCover.PCalc Else 'P' End as PCalc,   
Case when TOI.ADJMETHOD='OVERLIMIT ' then A1.CPCT else (Case When A1.CPCT<>0 then A1.CPCT else 100 end*cast(datediff(day, case when RCOVER.SDATE<A2.PDATE then A2.PDATE Else RCOVER.SDATE end, Case When RCOVER.EDATE>A2.PPDATE then A2.PPDATE ELSE RCOVER.EDATE end) as float)/  cast(DATEDIFF(DAY,A1.SDATE, A1.EDATE) as float)) end as PPRORATA,   
ICOVER.CURRENCY,   
ICOVER.SI,   
(Select sum(DDiscount) from AccDed Where ANO=ICover.ANO and Currency=ICover.Currency and TOR=RateCov.TOR) as DDISCOUNT,
ICOVER.Adjustable,   
ICOVER.PCTADJ,   
TOI.ADJMETHOD,   
ICOVER.INO,   
A2.ANO AS SANO,   
PolicyType.SType   
FROM  RCLASS, RATECOV, RCOVER, PCLASS, ICOVER, TOI, RCalc, COVER Left Join PolicyType on (PolicyType.PolicyType=Cover.PolicyType), ACCEPTANCE A1, ACCEPTANCE A2   
Where A1.PDate <= A2.PDate And A1.PPDate >= A2.PPDate And A2.PDate <= A2.PPDate   
and A1.ANO=@P_ANO and A2.OANO=A1.OANO and A2.ANO<=A1.PANO and A2.ANO<@P_ANO and A2.AType not in ('A','C') and Cover.CNO=A1.CNO   
and ICOVER.ANO=A1.ANO and ICOVER.Adjustable=1   
and RCOVER.ANO=A2.ANO   
and RATECOV.CODE=RCOVER.CODE   
and RCLASS.TOC=COVER.TOC   
and RCLASS.TOR=RATECOV.TOR   
and PCLASS.TOR=RATECOV.TOR   
and PCLASS.TOI=ICOVER.TOI   
and TOI.TOI=ICOVER.TOI   
and RCalc.ANO=A2.ANO and RCalc.Currency=ICover.Currency and RCalc.Code=RCover.Code and RCalc.TOR=RateCov.TOR and RCalc.SDate=RCover.SDate   
and NOT EXISTS (Select PANO from Acceptance A3 Where A3.PANO=A2.ANO and A3.AStatus<>'C' and A3.AType='A' and A3.ANO<>@P_ANO)   
and (TOI.ADJMETHOD<>'OVERLIMIT' or A2.ANO=A1.PANO)   
ORDER BY ICOVER.CURRENCY, RCOVER.CODE, RATECOV.TOR, RCOVER.SDATE, A2.ANO   
GO

--1 March 2017


IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QREINSURANCE_RATE') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE QREINSURANCE_RATE END
GO
CREATE Procedure QREINSURANCE_RATE(@P_ANO integer, @P_CURRENCY varchar(10)) 
as 
SELECT ReRate.Rate, ReRate.CCYTo 
From Acceptance 
Inner Join Cover on (Cover.CNO=Acceptance.CNO) 
Left Join RArrHeader on (RArrHeader.ANO=Acceptance.ANO) 
Inner Join ReRate on ( 
ReRate.TOC=Cover.TOC 
and ReRate.RYear=coalesce(( 
	Select Top 1 R1.RYear 
	from Reinsurance R1, ReClass R2 
	Left Join RePolicy R3 on (R3.RNO=R2.RNO and R3.ID=Cover.PHolder) 
	Where (R1.Category<>'P' or Coalesce(R3.ID,'')<>'') and R1.RType='Q' and R2.RNO=R1.RNO and R2.TOC=Cover.TOC and RArrHeader.RDate Between R1.SDate and R1.EDate 
	Order By Case When R1.RID=RArrHeader.QID Then 1 else 0 end Desc, coalesce(R3.ID,'') Desc, (Case When R2.PriorityF=1 Then R2.PriorityF else R1.PriorityF end) Desc),Year(RArrHeader.RDate)) 
And ReRate.Currency=@P_Currency) 
WHERE Acceptance.ANO=@P_ANO 
 
GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QCLAIM_RATE') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE QCLAIM_RATE END
GO
CREATE Procedure QCLAIM_RATE(@P_CNO integer, @P_CURRENCY varchar( 10))
as
SELECT ReRate.CRate, ReRate.CCYTo 
From Claim
Inner Join Acceptance on (Acceptance.ANO=Claim.ANO)
Inner Join Cover on (Cover.CNO=Acceptance.CNO) 
Left Join RArrHeader on (RArrHeader.ANO=Acceptance.ANO) 
Inner Join ReRate on ( 
ReRate.TOC=Cover.TOC 
and ReRate.RYear=coalesce(( 
	Select Top 1 R1.RYear 
	from Reinsurance R1, ReClass R2 
	Left Join RePolicy R3 on (R3.RNO=R2.RNO and R3.ID=Cover.PHolder) 
	Where (R1.Category<>'P' or Coalesce(R3.ID,'')<>'') and R1.RType='Q' and R2.RNO=R1.RNO and R2.TOC=Cover.TOC and RArrHeader.RDate Between R1.SDate and R1.EDate 
	Order By Case When R1.RID=RArrHeader.QID Then 1 else 0 end Desc, coalesce(R3.ID,'') Desc, (Case When R2.PriorityF=1 Then R2.PriorityF else R1.PriorityF end) Desc),Year(RArrHeader.RDate)) 
And ReRate.Currency=@P_Currency) 
WHERE Claim.CNO=@P_CNO
GO
--1 March  2017 (1)
IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'CLVIEW07L') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE CLVIEW07L END
GO
CREATE PROCEDURE CLVIEW07L(@P_CNO AS INTEGER)  
AS  
SELECT ClaAss.AdmNo, ClaAss.RefNo, ClaAss.BillDate, ClaAss.ClaimNo, ClaAss.ID, Profile.Name, ClaAss.Type, ClaAss.Currency as Currency_OC,  
'CLAIM'=sum(  
CASE  
        WHEN CLAASS.CODE='A' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'DEDUCTIBLE'=sum(  
CASE  
        WHEN CLAASS.CODE='E' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'COST'=sum(  
CASE  
        WHEN CLAASS.CODE='L' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'SALVAGE'=sum(  
CASE  
        WHEN CLAASS.CODE='S' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'SUBROGATION'=sum(  
CASE  
        WHEN CLAASS.CODE='R' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'ADJUSTMENT'=sum(  
CASE  
        WHEN CLAASS.CODE='I' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'PREMIUM'=sum(  
CASE  
        WHEN CLAASS.CODE='P' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'VAT'=sum(  
CASE  
        WHEN CLAASS.CODE='V' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'TAX'=sum(  
CASE  
        WHEN CLAASS.CODE='T' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'FEE'=sum(  
CASE  
        WHEN CLAASS.CODE='F' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
'DUTY'=sum(  
CASE  
        WHEN CLAASS.CODE='D' THEN ClaAss.AMOUNT  
        ELSE 0  
END),  
ClaAss.Posted AS Posted  
FROM ClaAss Left Join Admlink on (Admlink.AdmNo=ClaAss.AdmNo), Profile  
WHERE Profile.ID=ClaAss.ID And ClaAss.CNO=@P_CNO  
GROUP BY ClaAss.AdmNo, ClaAss.RefNo, ClaAss.BillDate, ClaAss.ClaimNo, ClaAss.ID, Profile.Name, ClaAss.Type, ClaAss.Currency, ClaAss.Posted        
GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'View07A') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE View07A END
GO
CREATE PROCEDURE View07A (@p_ANo as integer)              
AS              
SELECT AccAss.ID, Profile.Name, AccAss.Type, AccAss.Posted, AccAss.Admno, AccAss.Currency, Acceptance.RegNo, Accass.DocNo, AccAss.RefNo,      
Case When AccAss.CAmount=0 and Coalesce(pAcceptance.Branch,'')<>'' Then pAcceptance.Branch Else Acceptance.Branch end Branch,   
dbo.fn_Get_UWYear(MAcceptance.SDate, MAcceptance.EDate, Case When (Case When isnull(APayor.ANO,0)=0 Then (Case When isnull(MPayor.ANO,0)=0 Then Payor.PolicyYearF else MPayor.PolicyYearF end) else APayor.PolicyYearF end)=1 Then AccAss.SDate else Acceptance.SDate end) as PolicyYear,
sum(                
 case                
  when (accass.type in ('IR','IT','IX') and accass.code in ('P','U','F')) or (accass.type in ('DI','IC') and accass.code in ('P','U')) or (AccAss.Type not in ('DI','IC','IR','IT','IX') and AccAss.Code='P') then accass.Amount                
  else 0                
 end                
) AS Premium,                 
sum(                
 case                 
  when accass.code='C' then accass.Amount                
  else 0                
 end                
) AS Commision,                 
sum(                
 case                 
  when accass.Type not in ('IR','IT','IX') and accass.code='F' then accass.Amount                
  else 0                
 end                
) AS Fee,                 
sum(                
 case                 
  when accass.code='D' then accass.Amount                
  else 0                
 end                
) AS Duty,                 
sum(                
 case                 
  when accass.code='O' then accass.Amount                
  else 0                
 end                
) AS Discount,                 
sum(                
 case                
  when accass.code='I' then accass.Amount                
  else 0                
 end                
) AS OtherIncome,               
sum(                
 case                
  when accass.type in ('IR','IT','IX') and accass.code='F' then -accass.Amount
  when accass.Type in ('DI','IC') and accass.code='U' then -accass.Amount        
  when accass.Type Not in ('DI','IC') and accass.code='U' then accass.Amount        
  else 0                
 End                
) AS Ujroh,              
sum(                
 case                
  when (accass.type in ('IR','IT','IX') and accass.code in ('P','U'))  or (accass.type in ('DI','IC') and accass.code in ('P')) or (AccAss.Type not in ('DI','IC','IR','IT','IX') and AccAss.Code in ('P','U')) then accass.Amount                
  else 0                
 end                
) AS Tabarru,         
sum(                
 case                
  when (accass.code in ('J')) then accass.Amount                
  else 0                
 end                
) AS Deposit,          
sum(Case When coalesce((Admlink.Amount-Admlink.Amount_11-Admlink.Amount_12-Admlink.Amount_13-Admlink.Amount_14),0)<>0 then Admlink.Amount_11*AccAss.amount/(Admlink.Amount-Admlink.Amount_11-Admlink.Amount_12-Admlink.Amount_13-Admlink.Amount_14) else 0 end) as Rounding,        
sum(Case When coalesce((Admlink.Amount-Admlink.Amount_11-Admlink.Amount_12-Admlink.Amount_13-Admlink.Amount_14),0)<>0 then Admlink.Amount_13*AccAss.amount/(Admlink.Amount-Admlink.Amount_11-Admlink.Amount_12-Admlink.Amount_13-Admlink.Amount_14) else 0 end) as VAT,        
sum(Case When coalesce((Admlink.Amount-Admlink.Amount_11-Admlink.Amount_12-Admlink.Amount_13-Admlink.Amount_14),0)<>0 then Admlink.Amount_14*AccAss.amount/(Admlink.Amount-Admlink.Amount_11-Admlink.Amount_12-Admlink.Amount_13-Admlink.Amount_14) else 0 end) as TAX    
FROM AccAss 
Inner Join Acceptance on (Acceptance.ANO=AccAss.ANO)
Left Join APayor on (APayor.ANO=Acceptance.ANO and Acceptance.LANO<>-1 and Acceptance.ANO<>Acceptance.LANO)                              
Left Join Payor on (Payor.ANO=Acceptance.ANO and Acceptance.LANO=-1)              
Left Join Acceptance pAcceptance on (pAcceptance.ANO=Acceptance.pANO)
Left Join Admlink on (Admlink.AdmNo=AccAss.AdmNo)
Inner Join Profile on (Profile.ID=AccAss.ID)
Inner Join Acceptance mAcceptance on (Acceptance.RegNo=mAcceptance.RegNo and MAcceptance.ANO=MAcceptance.LANO)
Left Join Payor MPayor on (MPayor.ANO=mAcceptance.ANO)      
WHERE MAcceptance.ANO=@P_ANO        
GROUP BY AccAss.ID, Profile.Name, AccAss.Type, AccAss.Posted, AccAss.Admno, AccAss.Currency, Acceptance.RegNo, Accass.DocNo, AccAss.RefNo,      
Case When AccAss.CAmount=0 and Coalesce(pAcceptance.Branch,'')<>'' Then pAcceptance.Branch Else Acceptance.Branch end,   
dbo.fn_Get_UWYear(MAcceptance.SDate, MAcceptance.EDate, Case When (Case When isnull(APayor.ANO,0)=0 Then (Case When isnull(MPayor.ANO,0)=0 Then Payor.PolicyYearF else MPayor.PolicyYearF end) else APayor.PolicyYearF end)=1 Then AccAss.SDate else Acceptance.SDate end)
GO

