IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QCheck_Coverage') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE QCheck_Coverage END
