CREATE PROCEDURE QCheck_Coverage (@P_ANO as integer) 
AS
SELECT 'Interest' as Type, ICover.Remark
FROM 	ICover
WHERE ICover.ANO=@P_ANO 
and Not Exists (Select Top 1 PClass.TOI from RateCov, RCover, PClass Where RateCov.Code=RCover.Code and PClass.TOI=ICover.TOI and PClass.TOR=RateCov.TOR and RCover.ANO=@P_ANO)

union all

SELECT 'Risk' as Type, RCover.Remark
FROM 	RCover
WHERE RCover.ANO=@P_ANO 
and Not Exists (Select Top 1 RateCov.Code from RateCov, ICover, PClass Where ICover.SI<>0 and RateCov.Code=RCover.Code and PClass.TOI=ICover.TOI and PClass.TOR=RateCov.TOR and ICover.ANO=@P_ANO)

GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QOverlapped_Risk') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE QOverlapped_Risk END
GO
CREATE Procedure QOverlapped_Risk(@P_ANO integer) 
as 
Select Top 1 A1.ANO 
from RCover R1, Acceptance A1 
Where A1.ANO=@P_ANO and A1.ANO=R1.ANO and R1.Category='M' 
and not ((R1.SDate=A1.SDate or  R1.SDate=A1.PDate) and R1.EDate=A1.EDate) 
and Exists
( 
Select Top 1 R2.ANO 
from RCover R2 
Where R2.ANO=R1.ANO and R2.Category='M' and not (R2.Sdate=R1.Sdate) 
and 
( 
(R2.Sdate<R1.Edate and R2.Edate>=R1.Edate) or (R2.Sdate<=R1.Sdate and R2.Edate>R1.Sdate) or 
(R1.Sdate<=R2.Sdate and R1.Edate>R2.Sdate) or (R1.Sdate<R2.Edate and R1.Edate>=R2.Edate) 
) 
) 
 
GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QMissing_Risk') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE QMissing_Risk END
GO
CREATE  procedure QMissing_Risk(@P_ANO integer) 
as 
Select Top 1 A1.ANO 
from RCover R1, Acceptance A1 
Where A1.ANO=@P_ANO and A1.ANO=R1.ANO 
and (R1.Category='A' or not ((R1.SDate=A1.SDate or  R1.SDate=A1.PDate) and R1.EDate=A1.EDate)) 
and Not Exists
( 
Select Top 1 R2.ANO 
from RCover R2 
Where R2.Category='M' and R2.ANO=R1.ANO and not (R2.Code=R1.Code and R2.Sdate=R1.Sdate) 
and 
( 
(R2.Sdate<=R1.Edate and R2.Edate>=R1.Edate) or (R2.Sdate<=R1.Sdate and R2.Edate>=R1.Sdate) or 
(R1.Sdate<=R2.Sdate and R1.Edate>=R2.Sdate) or (R1.Sdate<=R2.Edate and R1.Edate>=R2.Edate) 
) 
) 
 go

