if exists (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'Get_Open_Item_N') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) )
BEGIN DROP FUNCTION Get_Open_Item_N END
GO
CREATE function Get_Open_Item_N (@P_Voucher Varchar(20))      

RETURNS Table      

AS RETURN      

(      
 Select Top 1 Voucher.Voucher, Account.Account, Account.Description, Voucher.Branch, Voucher.CT, SL.Hint, Case When Voucher.DebtorF=1 Then (Voucher.Nominal_CC-Voucher.Diff_CC) else -(Voucher.Nominal_CC-Voucher.Diff_CC) end as Nominal_OC      
 from nVoucher Voucher inner Join nSL SL on (SL.Voucher=Voucher.Voucher) inner Join Account on (Account.Account=SL.Account and Account.Open_ItemF=1)      
 Where Voucher.Voucher=@P_Voucher      
 and Voucher.SL_Tag=0	-- Not Manual Voucher
 order by SL.hint Desc

)                  


GO

if exists (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'Get_Open_Item_M') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) )
BEGIN DROP FUNCTION Get_Open_Item_M END
GO
CREATE function Get_Open_Item_M (@P_Voucher Varchar(20))  
RETURNS Table  
AS RETURN  
(  
 Select Voucher.Voucher, Account.Account, Account.Description, Max(Voucher.Branch) as Branch, Max(Voucher.CT) as CT, Max(SL.Hint) as Hint, sum(Case When Voucher.DebtorF=1 Then SL.Nominal else -SL.Nominal end) as Nominal_OC  
 from nVoucher Voucher, nSL SL, VType, VPattern, Account  
 Where Voucher.Voucher=@P_Voucher and Voucher.InvestmentF=0 and Vtype.TaxF=0 and Voucher.Voucher=SL.Voucher 
 and VType.VType=Voucher.VType and VPattern.VType=VType.VType 
 and (VPattern.Debit=SL.Hint or VPattern.Credit=SL.Hint) and Account.Account=VPattern.Account and Account.Open_ItemF=1  
 and Voucher.SL_Tag=1	-- Manual Voucher
 Group by Voucher.Voucher, Account.Account, Account.Description  

)  

go


--UPDATE QA
if exists (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'fn_Get_UWYear') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) )
BEGIN DROP FUNCTION fn_Get_UWYear END
GO
CREATE FUNCTION fn_Get_UWYear (@P_SDate as DateTime, @P_EDate as DateTime, @P_PDate as DateTime)              
RETURNS Integer            
AS               
BEGIN              
Declare @P_UWYear as integer            
Declare @P_PolicyYear as integer            
if datediff(day, @P_PDate, @P_EDate)<0             
begin            
Select @P_PDate=@P_Edate            
end            
if datediff(day, @P_PDate, @P_Sdate)>0             
begin            
Select @P_PDate=@P_SDate            
end            
           
Select @P_PolicyYear = datediff(year,@P_Sdate, @P_PDate)            
if datediff(day,dateadd(year,@P_PolicyYear, @P_SDate),@P_PDate)<0            
begin            
Select @P_PolicyYear=@P_PolicyYear-1            
end            
          
if datediff(year,@P_SDate, @P_EDate)-1<@P_PolicyYear           
begin          
Select @P_PolicyYear=datediff(year,@P_Sdate,@P_EDate)-1          
end          
          
Select @P_UWYear=year(@P_Sdate)+@P_PolicyYear              
           
return(@P_UWYear)              
END         
       
GO
 

