GO
CREATE  FUNCTION MList03_DET (@P_ANO AS INTEGER,@P_USERID as Varchar(50)) 
RETURNS TABLE
AS RETURN(
SELECT  Cast(0 as bit) as ProcessFlag, 
	Cover.COVERNO, 
	Acceptance.AName, 
	Acceptance.CertificateNo, 
	Cover.CNO, 
	Cover.CStatus, 
	Cover.VSeqNo, 
	Acceptance.LANO, 
	Acceptance.ANO, 
	Acceptance.REGNO, 
	Acceptance.ADATE, 
	Acceptance.USERID, 
	SysTab.Currency, 
	QPCalc.TSI, 
	QPCalc.OurShare, 
	QPCalc.Gross, 
	Acceptance.ASTATUS, 
	Acceptance.ATYPE, 
	Acceptance.SDate, 
	Acceptance.EDate, 
	Year(RArrheader.Rdate) AS RYear
FROM 
	Acceptance, 
	Cover, 
	RArrHeader, 
	SysTab, 
	QMasterAcceptance_PCalc() AS QPCalc
WHERE 
	Cover.CNO=Acceptance.CNO 
	And RArrHeader.ANO=Acceptance.ANO 
	And QPCalc.ANO=Acceptance.ANO 
	And Acceptance.ANO<>Acceptance.LANO 
	And Acceptance.LANO=@P_ANO 
	And Acceptance.AType='N' 
	And Acceptance.AStatus='C' 
	And Cover.CStatus='C'
	And Acceptance.LUserID Like @P_UserID
)



GO


