IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QCheck_ContractNo_SysBatchSC') and OBJECTPROPERTY(id, N'IsProcedure') = 1 ) BEGIN DROP PROCEDURE QCheck_ContractNo_SysBatchSC END
GO
CREATE Procedure QCheck_ContractNo_SysBatchSC(@ContractNo as varchar(50),@ORDERNO AS varchar(50),@DOCNO AS varchar(50),@POLICYNO AS VARCHAR(50)) 
as 
SELECT  Top 1 
S2.BID, 
S2.PolicyNo as [Policy No], 
S2.Insured, 
S2.Inception, 
S2.Expiry, 
S2.ANO 
from 
SysBatchSC S2, 
SysBatchH S1 
Where 
S1.BatchNO = S2.BatchNO 
and S1.Status in ('R','P') 
and S2.Status in ('W','N') and S2.ErrMsg in ('','On-Progress...')
and S2.PolicyNo=@POLICYNO and S2.ContractNo=@ContractNo and S2.ORDERNO=@ORDERNO and S2.DOCNO=@DOCNO 
 
 

GO


