TOC.FLDID13, TOC.FLDTAG13, TOC.FLDTAGA13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDCOMA AS FLDCOMA13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  GENHTAB_13.FLDSEARCH AS FLDSEARCH13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13, GENHTAB_13.FLDCHGINF as FLDCHGINF13, GENHTAB_13.FLDLOWER as FLDLOWER13, GENHTAB_13.FLDUPPER as FLDUPPER13,
TOC.FLDID14, TOC.FLDTAG14, TOC.FLDTAGA14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDCOMA AS FLDCOMA14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  GENHTAB_14.FLDSEARCH AS FLDSEARCH14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14, GENHTAB_14.FLDCHGINF as FLDCHGINF14, GENHTAB_14.FLDLOWER as FLDLOWER14, GENHTAB_14.FLDUPPER as FLDUPPER14,
TOC.FLDID15, TOC.FLDTAG15, TOC.FLDTAGA15, GENHTAB_15.FLDTAB AS FLDTAB15, GENHTAB_15.FLDCOM AS FLDCOM15, GENHTAB_15.FLDCOMA AS FLDCOMA15, GENHTAB_15.FLDDFORMAT AS FLDDFORMAT15, GENHTAB_15.FLDIFORMAT AS FLDIFORMAT15, GENHTAB_15.FLDTYPE AS FLDTYPE15, GENHTAB_15.SUBLINKF AS SUBLINKF15,  GENHTAB_15.FLDSEARCH AS FLDSEARCH15, GENHTAB_15.FLDCRITERIA AS FLDCRITERIA15, GENHTAB_15.FLDCHGINF as FLDCHGINF15, GENHTAB_15.FLDLOWER as FLDLOWER15, GENHTAB_15.FLDUPPER as FLDUPPER15
